"""Targeted curriculum extensions for Learn Language Academy by Parth.

These 12 lessons fill assessed CEFR progression gaps in the existing 90-lesson
course. Internal IDs 91-102 remain stable for learner progress; app.py inserts
them pedagogically into the visible course sequence.
Each lesson uses the shared lesson-data contract plus objectives, pronunciation
and homework. English explanations; standard French first, Canadian notes labelled.
"""

LESSON_SPECS = {
91: {
"level":"A1 – Absolute Beginner",
"title":"Basic Sentence Patterns, Word Order and Negation",
"goal":"Build clear affirmative, negative and simple question sentences using familiar vocabulary.",
"objectives":["Identify subject, verb and complement in a simple sentence.","Build statements with être, avoir and common present-tense verbs.","Form basic negatives with ne…pas and recognise spoken omission of ne.","Ask simple yes/no questions using intonation and est-ce que."],
"vocab":[("une phrase","a sentence","ün frahz","/yn fʁaz/","Une phrase commence par une majuscule."),("le sujet","the subject","luh sü-zhay","/lə sy.ʒɛ/","Le sujet indique qui fait l'action."),("le verbe","the verb","luh vehrb","/lə vɛʁb/","Le verbe change selon le sujet."),("le complément","the complement","luh kohn-play-mahn","/lə kɔ̃.ple.mɑ̃/","J'apprends le complément de la phrase."),("souvent","often","soo-vahn","/su.vɑ̃/","Je lis souvent."),("jamais","never","zhah-may","/ʒa.mɛ/","Je ne fume jamais."),("encore","again; still","ahn-kohr","/ɑ̃.kɔʁ/","Elle travaille encore."),("parfois","sometimes","par-fwah","/paʁ.fwa/","Nous cuisinons parfois.")],
"grammar":[("Basic statement order","The neutral pattern is SUBJECT + VERB + COMPLEMENT: Je (subject) parle (verb) français (complement). French normally keeps this order in statements. A time or place phrase can be added: Je travaille à Luanda aujourd'hui."),("Être and avoir patterns","Être links a subject to identity or description: Elle est étudiante. Avoir expresses possession, age and many fixed states: Il a vingt ans. Do not translate English 'am/is/are' mechanically into avoir."),("Negation with ne…pas","Place ne before the conjugated verb and pas after it: Je ne parle pas. Before a vowel, ne becomes n': Je n'habite pas ici. In everyday speech, speakers often omit ne, but learners should recognise it and use the full form in careful writing."),("Simple questions","A yes/no question can use rising intonation (Tu viens ?), est-ce que (Est-ce que tu viens ?) or inversion in more formal language (Viens-tu ?). Est-ce que is a reliable beginner pattern."),("Adverbs of frequency","Often-used frequency adverbs such as souvent, parfois, rarement and toujours usually follow a simple conjugated verb: Je travaille souvent. With a compound tense, many short adverbs appear between the auxiliary and participle: J'ai souvent voyagé.")],
"expressions":[("Comment ça se passe ?","How is it going?","Natural way to ask how an activity or situation is progressing."),("Pas encore.","Not yet.","Useful short answer; encore means still/yet in this context."),("Je ne sais pas.","I don't know.","Common complete negative sentence."),("Est-ce que tu viens ?","Are you coming?","Neutral everyday question using est-ce que.")],
"examples":[("Je parle français à la maison.","I speak French at home.","Subject je + verb parle + complement français + place phrase."),("Nous n'avons pas de voiture.","We do not have a car.","Ne…pas surrounds the conjugated verb; un/une/des usually become de after a negative."),("Est-ce que vous travaillez aujourd'hui ?","Are you working today?","Est-ce que introduces a yes/no question without changing statement word order."),("Elle ne regarde jamais la télévision.","She never watches television.","Jamais replaces pas as the negative word; ne remains before the verb."),("Tu étudies encore ?","Are you still studying?","Rising intonation can form a natural informal question.")],
"conversations":[("Making a simple plan",[("A","Tu travailles aujourd'hui ?"),("B","Non, je ne travaille pas aujourd'hui."),("A","Est-ce que tu veux prendre un café ?"),("B","Oui, avec plaisir !")],"A: Are you working today? B: No, I am not working today. A: Do you want to have a coffee? B: Yes, gladly!"),("Checking information",[("A","Est-ce que Marie habite ici ?"),("B","Non, elle n'habite pas ici. Elle habite à Montréal."),("A","Ah, d'accord. Merci !"),("B","Pas de problème.")],"A: Does Marie live here? B: No, she doesn't live here. She lives in Montreal. A: Oh, okay. Thanks! B: No problem.")],
"pronunciation":["Keep the final consonant of pas audible; do not pronounce the final s in jamais.","In connected speech, ne may be reduced or omitted informally; learn to recognise both forms.","Keep question intonation natural: raise the pitch gently at the end rather than stressing every word."],
"exercises":[("Choose the correct neutral word order.",["Je français parle.","Je parle français.","Parle je français.","Français je parle."],1,"The neutral order is subject + verb + complement."),("Choose the correct negative.",["Je ne parle français pas.","Je pas ne parle français.","Je ne parle pas français.","Je parle ne pas français."],2,"Ne comes before the conjugated verb and pas after it."),("Which is a standard yes/no question?",["Est-ce que tu viens ?","Que tu viens est ?","Est-ce tu que viens ?","Tu est-ce viens ?"],0,"Est-ce que is followed by normal statement word order."),("Complete: Elle ___ jamais en retard.",["ne est","n'est","est ne","pas est"],1,"Elision gives n'est; jamais supplies the negative meaning."),("Which word means 'sometimes'?",["toujours","jamais","parfois","encore"],2,"Parfois means sometimes."),("Choose the correct sentence.",["Nous n'avons pas de voiture.","Nous ne avons pas une voiture.","Nous avons ne pas voiture.","Nous pas avons de voiture."],0,"Ne becomes n' before avons; a negative de appears before the noun.")],
"speaking":["Say five statements aloud, then turn each into a negative sentence.","Ask a partner or imagine asking six yes/no questions with est-ce que.","Describe your weekly routine using toujours, souvent, parfois and jamais.","Read both dialogues aloud, changing the names, places and activities."],
"summary":["French statements usually follow subject + verb + complement.","Ne…pas surrounds the conjugated verb; ne becomes n' before a vowel.","Est-ce que forms clear yes/no questions without inversion.","Frequency adverbs add useful detail and have typical positions."],
"homework":["Write eight affirmative sentences about your life.","Rewrite four of them as negatives, using pas, jamais or plus where appropriate.","Write six yes/no questions using est-ce que and answer each in a full sentence.","Read your sentences aloud and mark the subject and verb."]
},
92: {
"level":"A1 – Absolute Beginner","title":"Possessive and Demonstrative Determiners",
"goal":"Identify who owns something and point to specific people or objects using correct French determiners.",
"objectives":["Choose mon, ma, mes and other possessive forms.","Use ce, cet, cette and ces to identify a noun.","Apply agreement with the noun rather than the owner's gender.","Recognise the vowel rule in feminine possessives."],
"vocab":[("mon / ma / mes","my","mohn / mah / may","/mɔ̃ ma me/","Voici mon livre et ma clé."),("ton / ta / tes","your (informal)","tohn / tah / tay","/tɔ̃ ta te/","Où sont tes clés ?"),("son / sa / ses","his / her / its","sohn / sah / say","/sɔ̃ sa se/","Elle cherche son sac."),("notre / nos","our","noh-truh / noh","/nɔtʁ no/","Notre maison est petite."),("votre / vos","your (formal/plural)","voh-truh / voh","/vɔtʁ vo/","Voici vos documents."),("leur / leurs","their","luhr / luhr","/lœʁ/","Leurs enfants sont ici."),("ce","this/that (masculine)","suh","/sə/","Ce livre est intéressant."),("cette / ces","this/that feminine; these/those","set / say","/sɛt se/","Cette chaise est libre; ces tables sont libres.")],
"grammar":[("Possessives agree with the thing owned","Mon, ma and mes mean my, but the form depends on the noun: mon frère, ma sœur, mes amis. The owner's gender does not determine the form."),("Feminine nouns before vowels","Use mon, ton or son before a feminine singular noun beginning with a vowel or silent h to avoid two vowel sounds: mon amie, ton école, son histoire. The noun remains feminine."),("Full possessive table","Singular owner forms: mon/ma/mes, ton/ta/tes, son/sa/ses. Plural owners: notre/nos, votre/vos, leur/leurs. The determiner agrees with the possessed noun in number and, where relevant, gender."),("Demonstratives","Use ce before most masculine singular nouns, cet before a masculine singular noun beginning with a vowel or silent h, cette before feminine singular nouns and ces before plural nouns: ce garçon, cet arbre, cette maison, ces livres."),("Possessive vs demonstrative","Possessives show a relationship or ownership; demonstratives point something out. Compare mon livre (my book) and ce livre (this/that book). French ce does not distinguish this from that without context.")],
"expressions":[("C'est à qui ?","Whose is it?","Useful when asking who owns an object."),("C'est à moi.","It's mine.","A common ownership response; à toi/à lui/à elle/à nous/à vous/à eux are alternatives."),("Voici mon…","Here is my…","Useful when presenting an object or person."),("Cette fois-ci","This time","Demonstrative expression used to distinguish the current occasion.")],
"examples":[("Mon amie habite près de cette école.","My friend lives near this school.","Mon precedes feminine amie because it begins with a vowel; cette agrees with école's feminine gender."),("Ces étudiants cherchent leurs salles.","These students are looking for their rooms.","Ces points to plural students; leurs agrees with plural salles."),("Cet appartement est plus grand que ma maison.","This apartment is bigger than my house.","Cet is used before masculine appartement beginning with a vowel."),("Notre professeur connaît vos noms.","Our teacher knows your names.","Notre and vos show relationships to singular and plural possessed nouns.")],
"conversations":[("Finding a lost item",[("A","Est-ce que c'est ton téléphone ?"),("B","Non, ce n'est pas le mien. C'est peut-être son téléphone."),("A","Je vais demander à cette étudiante."),("B","Bonne idée !")],"A: Is this your phone? B: No, it isn't mine. Maybe it's her phone. A: I'll ask this student. B: Good idea!"),("Introducing family",[("A","Voici ma sœur et mes parents."),("B","Enchanté ! Et ces enfants ?"),("A","Ce sont leurs enfants."),("B","Ils sont très gentils !")],"A: Here are my sister and my parents. B: Nice to meet you! And these children? A: They are their children. B: They are very kind!")],
"pronunciation":["Mon, ton and son have nasal vowels; do not pronounce a separate final N.","Ce and se sound alike in many contexts; spelling and grammatical role distinguish them.","Cet ends in a pronounced /t/ before its following noun in ordinary connected speech."],
"exercises":[("Choose the correct form: ___ amie.",["ma","mon","mes","notre"],1,"Mon is used before a feminine singular noun beginning with a vowel."),("Choose the correct demonstrative: ___ arbre.",["ce","cet","cette","ces"],1,"Cet precedes a masculine singular noun beginning with a vowel."),("Possessive determiners agree with…",["the owner only","the possessed noun","the speaker's gender","the verb"],1,"The form agrees with the noun being possessed."),("Complete: ___ maisons sont anciennes.",["ce","cet","cette","ces"],3,"Ces is the plural demonstrative."),("Which means 'our books'?",["notre livres","nos livres","leurs livre","ma livres"],1,"Nos is the plural form of notre."),("Which phrase asks 'Whose is it?'",["C'est à qui ?","C'est où ?","C'est combien ?","C'est quand ?"],0,"C'est à qui asks who owns it.")],
"speaking":["Describe five objects around you using possessives.","Point to objects and say ce, cet, cette or ces with each noun.","Explain the difference between mon sac and ce sac.","Practise the lost-item dialogue with three different objects."],
"summary":["Possessive forms agree with the possessed noun, not the owner's gender.","Use mon/ton/son before feminine singular nouns beginning with a vowel or silent h.","Ce, cet, cette and ces are demonstratives.","Use context to distinguish this from that."],
"homework":["Write ten noun phrases using possessive determiners.","Write eight noun phrases using demonstratives, including cet before vowel-starting masculine nouns.","Describe your family and belongings in a short paragraph.","Check every determiner against the gender and number of its noun."]
},
93: {
"level":"A2 – Elementary","title":"Partitive Articles, Quantity and Food Expressions","goal":"Talk accurately about uncountable food, drink and quantities using partitive and quantity constructions.",
"objectives":["Distinguish definite, indefinite and partitive articles.","Use du, de la, de l' and des for unspecified quantities.","Apply de after negative and quantity expressions.","Order and describe portions naturally."],
"vocab":[("du pain","some bread","dü pahn","/dy pɛ̃/","Je voudrais du pain."),("de la soupe","some soup","duh lah soop","/də la sup/","Elle mange de la soupe."),("de l'eau","some water","duh loh","/də lo/","Nous buvons de l'eau."),("des légumes","some vegetables","day lay-güm","/de le.ɡym/","Il achète des légumes."),("une tranche","a slice","ün trahnsh","/yn tʁɑ̃ʃ/","Une tranche de fromage, s'il vous plaît."),("un morceau","a piece","uhn mohr-soh","/œ̃ mɔʁ.so/","Je prends un morceau de gâteau."),("assez de","enough","ah-say duh","/a.se də/","Nous avons assez de temps."),("un peu de","a little","uhn puh duh","/œ̃ pø də/","Ajoutez un peu de sel.")],
"grammar":[("Partitive articles","Use du (masculine), de la (feminine), de l' (before vowel/silent h) and des (plural) for an unspecified amount: du riz, de la confiture, de l'huile, des pâtes. The article often means some or any in English."),("Choosing the right article","Use a definite article for something in general (J'aime le café), an indefinite article for a countable item (un café can mean a coffee), and a partitive for an unspecified amount (Je bois du café). Meaning and context matter."),("Negation changes the article","After ne…pas, partitive and indefinite articles usually become de/d': Je mange du pain → Je ne mange pas de pain. The definite article remains: Je n'aime pas le café."),("Quantity expressions","After beaucoup, peu, assez, trop, combien and similar quantity words, use de/d': beaucoup de fromage, trop d'eau, assez de légumes. Do not add an article between the quantity word and de."),("Specific portions","Use a countable container or portion plus de: un verre d'eau, une tasse de thé, une tranche de pain, un kilo de pommes. The noun after de is not preceded by a partitive article.")],
"expressions":[("Je prendrai…","I'll have…","Natural when ordering food or drink."),("Sans sucre, s'il vous plaît.","Without sugar, please.","Sans is followed directly by a noun."),("Un peu plus de…","A little more…","Useful for adjusting a portion or recipe."),("Vous en voulez ?","Would you like some?","En replaces a quantity or de + noun; this previews object pronouns.")],
"examples":[("Je voudrais de l'eau et du pain.","I would like some water and some bread.","De l' is used before vowel-starting eau; du is masculine singular."),("Elle ne mange pas de viande.","She does not eat meat.","Partitive de la becomes de after the negative."),("Nous achetons beaucoup de fruits.","We buy a lot of fruit.","Beaucoup is followed by de, not des."),("Il prend une tasse de café.","He is having a cup of coffee.","A container expression is followed by de."),("J'aime le fromage, mais je ne mange pas beaucoup de fromage.","I like cheese, but I don't eat much cheese.","General preference uses le; quantity uses beaucoup de.")],
"conversations":[("At a bakery",[("Client","Bonjour. Je voudrais une baguette et deux croissants."),("Vendeur","Bien sûr. Autre chose ?"),("Client","Oui, un peu de fromage, s'il vous plaît."),("Vendeur","Voilà. Ça fait huit dollars.")],"Customer: Hello. I would like a baguette and two croissants. Seller: Of course. Anything else? Customer: Yes, a little cheese, please. Seller: Here you are. That comes to eight dollars."),("Discussing a recipe",[("A","Il faut combien de lait ?"),("B","Un demi-litre de lait et deux œufs."),("A","Et du sucre ?"),("B","Oui, mais pas trop de sucre.")],"A: How much milk is needed? B: Half a litre of milk and two eggs. A: And some sugar? B: Yes, but not too much sugar.")],
"pronunciation":["Du is /dy/; do not confuse its vowel with /u/ in doux.","The final consonants in beaucoup and trop are normally silent in isolation.","Link de l'eau smoothly; the apostrophe marks elision before a vowel."],
"exercises":[("Choose the correct article: ___ eau.",["du","de la","de l'","des"],2,"De l' is used before a vowel sound."),("Complete: Je ne bois pas ___ lait.",["du","de","le","des"],1,"The partitive becomes de after ne…pas."),("Complete: beaucoup ___ légumes.",["des","de","du","les"],1,"Quantity expressions such as beaucoup take de."),("Which means 'I like coffee in general'?",["J'aime du café.","J'aime le café.","Je n'aime pas de café.","Je bois un café."],1,"The definite article is used for general preferences."),("Complete: un verre ___ eau.",["du","de l'","des","la"],1,"A container expression uses de; before eau it becomes d'eau."),("Which is a countable portion?",["du fromage","de la soupe","une tranche de pain","de l'huile"],2,"Une tranche is a countable portion followed by de.")],
"speaking":["Describe what you eat and drink in a typical day, using at least six partitive forms.","Order a meal and ask for two changes politely.","Explain a simple recipe with quantities and containers.","Transform five positive food sentences into negative sentences."],
"summary":["Partitive articles express an unspecified amount: du, de la, de l', des.","Definite articles express general preferences; indefinite articles introduce countable items.","Use de after quantity expressions and usually after negation.","Use a portion/container + de for measurable amounts."],
"homework":["Write a food diary with at least twelve partitive expressions.","Write a recipe for a simple dish using quantity words and containers.","Write five negative food statements and explain the article change.","Practise ordering the meal dialogue aloud."]
},
94: {
"level":"A2 – Elementary","title":"Imperatives, Adverbs and Everyday Connectors","goal":"Give instructions, make requests and connect short ideas into natural everyday communication.",
"objectives":["Form affirmative and negative commands.","Use common adverbs of manner, frequency and time.","Connect ideas with mais, parce que, donc, puis and ensuite.","Make requests politely and choose appropriate register."],
"vocab":[("écoute","listen (tu command)","ay-koot","/e.kut/","Écoute bien."),("attendez","wait (vous command)","ah-tahn-day","/a.tɑ̃.de/","Attendez une minute."),("doucement","gently; slowly","doos-mahn","/dus.mɑ̃/","Parlez doucement."),("rapidement","quickly","rah-peed-mahn","/ʁa.pid.mɑ̃/","Il marche rapidement."),("d'abord","first","dah-bohr","/da.bɔʁ/","D'abord, lisez la question."),("ensuite","then; next","ahn-sweet","/ɑ̃.sɥit/","Ensuite, choisissez une réponse."),("pourtant","however; yet","poor-tahn","/puʁ.tɑ̃/","Il est fatigué; pourtant, il continue."),("donc","so; therefore","dohnk","/dɔ̃k/","Il pleut, donc je reste ici.")],
"grammar":[("Forming the imperative","The imperative uses tu, nous or vous verb forms without the subject pronoun: Écoute ! Écoutons ! Écoutez ! For regular -ER verbs, the tu form usually drops final -s: Parle ! But restore -s before y or en for sound and liaison: Vas-y !"),("Negative commands","Place ne…pas around the verb: Ne parle pas ! N'attendez pas ! Object pronouns appear after affirmative commands with hyphens (Donne-le-moi) and before the verb in negative commands (Ne me le donne pas)."),("Adverbs of manner","Many adverbs are formed from the feminine adjective + -ment: lentement, heureusement. Some are irregular, including bien, mal, mieux and vite. Many adverbs follow the verb: Elle parle doucement."),("Adverbs of frequency and time","Souvent, rarement, toujours and parfois usually follow a simple conjugated verb. D'abord, ensuite, puis and enfin organise steps or events. Placement can change for emphasis."),("Connecting ideas","Mais contrasts, parce que gives a reason, donc signals a result, puis/ensuite order actions, and pourtant introduces an unexpected contrast. Choose a connector based on the logical relationship, not as decoration.")],
"expressions":[("Faites attention !","Be careful!","A common plural/formal command."),("Vas-y !","Go ahead!","Affirmative imperative with y; the -s is retained."),("Ça dépend.","It depends.","Useful response when a situation has conditions."),("D'abord…, ensuite…","First…, then…","Clear sequence for instructions and explanations.")],
"examples":[("Lisez la consigne attentivement.","Read the instruction carefully.","Vous imperative; attentivement is an adverb of manner."),("Ne traverse pas la rue maintenant.","Don't cross the street now.","Negative tu command."),("Je prends le bus parce qu'il pleut.","I take the bus because it is raining.","Parce que introduces the reason."),("Il est tard, donc nous rentrons.","It is late, so we are going home.","Donc introduces the consequence."),("Elle travaille rapidement, mais soigneusement.","She works quickly but carefully.","Two adverbs describe how she works.")],
"conversations":[("Giving directions",[("A","Excusez-moi, comment aller à la gare ?"),("B","Continuez tout droit, puis tournez à gauche."),("A","D'accord. Et ensuite ?"),("B","Traversez la place. La gare est devant vous.")],"A: Excuse me, how do I get to the station? B: Continue straight, then turn left. A: Okay. And then? B: Cross the square. The station is in front of you."),("Helping a classmate",[("A","Je ne comprends pas cet exercice."),("B","Lis d'abord la question attentivement."),("A","Ensuite, je choisis une réponse ?"),("B","Oui. Et vérifie ton travail avant de finir.")],"A: I don't understand this exercise. B: First read the question carefully. A: Then I choose an answer? B: Yes. And check your work before finishing.")],
"pronunciation":["The final -s of a tu imperative is usually silent when absent, but is pronounced /z/ in liaison in vas-y and manges-en.","Adverb endings -ment are pronounced as a connected ending; avoid adding an extra syllable after the word.","Keep connectors unstressed but clear; pause lightly between ordered steps."],
"exercises":[("Choose the correct tu command for parler.",["Parles !","Parle !","Parlez !","Parlons !"],1,"The tu imperative of a regular -ER verb usually drops the final -s."),("Choose the negative command.",["Ne attends pas !","N'attends pas !","Pas attends !","N'attend ne pas !"],1,"Ne elides before a vowel; the negative surrounds the verb."),("Which connector gives a reason?",["donc","mais","parce que","pourtant"],2,"Parce que introduces a reason."),("Complete: Il pleut, ___ je prends un taxi.",["parce que","donc","mais","ensuite"],1,"Donc introduces a result."),("Which is an adverb of manner?",["lentement","demain","maison","souvent"],0,"Lentement describes how an action is done."),("Which is the correct affirmative command with y?",["Va-y !","Vas-y !","Y va !","Vas y !"],1,"The -s is retained before y in the affirmative imperative.")],
"speaking":["Give five instructions to a visitor using vous commands.","Explain a recipe or route using d'abord, ensuite, puis and enfin.","Give three negative commands and three polite requests.","Describe how you do everyday tasks using adverbs."],
"summary":["The imperative uses tu, nous or vous verb forms without subject pronouns.","Negative commands use ne…pas around the verb; affirmative pronouns follow with hyphens.","Adverbs describe how, when or how often something happens.","Connectors express reason, result, contrast and sequence."],
"homework":["Write a ten-step set of instructions using commands and sequence connectors.","Write six sentences containing adverbs of manner or frequency.","Create a polite notice with three affirmative and three negative commands.","Read your instructions aloud, pausing at logical points."]
},
95: {
"level":"B1 – Intermediate","title":"Past Participle Agreement and Auxiliary Choices","goal":"Choose avoir or être accurately in compound tenses and apply the most important past-participle agreement rules.",
"objectives":["Select the correct auxiliary for common verbs.","Agree être past participles with the subject.","Recognise agreement with a preceding direct object under avoir.","Handle reflexive verbs and common exceptions carefully."],
"vocab":[("l'auxiliaire","auxiliary verb","loh-zeg-zee-lyair","/loɡ.zi.ljɛʁ/","Avoir est un auxiliaire fréquent."),("le participe passé","past participle","luh par-tee-seep pah-say","/lə paʁ.ti.sip pa.se/","Écrit est le participe passé d'écrire."),("s'accorder","to agree","sah-kohr-day","/sa.kɔʁ.de/","Le participe passé peut s'accorder."),("un COD","direct object","uhn say-oh-day","/œ̃ se.o.de/","Le COD peut précéder le verbe."),("précéder","to come before","pray-say-day","/pʁe.se.de/","Le pronom précède l'auxiliaire."),("la plupart","most; the majority","lah plü-par","/la ply.paʁ/","La plupart des verbes utilisent avoir."),("une exception","an exception","ün ehk-sep-syohn","/yn ɛk.sɛp.sjɔ̃/","Il existe quelques exceptions."),("la tournure","the construction/wording","lah toor-nür","/la tuʁ.nyʁ/","Cette tournure exige un accord.")],
"grammar":[("Avoir is the default auxiliary","Most transitive and many intransitive verbs form the passé composé with avoir: j'ai mangé, nous avons fini, elle a dormi. The past participle normally does not agree with the subject when avoir is used."),("Être with movement and state verbs","A defined group of intransitive verbs commonly uses être (aller, venir, arriver, partir, entrer, sortir, naître, mourir, tomber, rester, retourner, etc.): Elle est arrivée; ils sont partis. The participle agrees with the subject: arrivée, partis."),("Reflexive verbs","Reflexive verbs use être in compound tenses: elle s'est levée. Agreement depends on the role and position of the reflexive pronoun and any direct object. Compare Elle s'est lavée (agreement) and Elle s'est lavé les mains (no agreement because les mains is the direct object after the verb)."),("Avoir with a preceding direct object","With avoir, the past participle agrees with a direct object only when that object comes before the verb: Les lettres que j'ai écrites; Je les ai écrites. No agreement in J'ai écrit les lettres. Identify the COD before applying the rule."),("Do not confuse indirect objects","An indirect object introduced by à does not trigger this agreement: Les personnes à qui j'ai parlé. Invariable cases and special constructions exist; learn the core patterns before memorising rare exceptions.")],
"expressions":[("Je me suis rendu compte que…","I realised that…","Common reflexive construction; the participle rendu does not agree in this fixed expression."),("Elles sont déjà parties.","They have already left.","Être auxiliary with feminine plural agreement."),("Les photos que j'ai prises","The photos that I took","The preceding direct object que refers to photos, so prises agrees."),("Ça m'est arrivé.","That happened to me.","A common être construction; agreement follows the subject/event.")],
"examples":[("Marie est arrivée à huit heures.","Marie arrived at eight o'clock.","Arriver takes être; feminine singular agreement adds -e."),("Paul et Marc sont descendus.","Paul and Marc went down.","Être auxiliary; masculine plural agreement."),("J'ai acheté les fleurs.","I bought the flowers.","Avoir; the direct object follows, so no agreement."),("Les fleurs que j'ai achetées sont magnifiques.","The flowers I bought are beautiful.","The preceding direct object que refers to feminine plural fleurs."),("Elle s'est lavé les mains.","She washed her hands.","Les mains is the direct object after the verb, so lavé remains unchanged.")],
"conversations":[("Talking about a trip",[("A","Vous êtes arrivées quand ?"),("B","Nous sommes arrivées hier soir."),("A","Et vous avez visité le Vieux-Québec ?"),("B","Oui, nous avons pris beaucoup de photos.")],"A: When did you arrive? B: We arrived last night. A: And did you visit Old Quebec? B: Yes, we took lots of photos."),("Correcting a report",[("A","J'ai vu les lettres que tu as envoyées."),("B","Tu as remarqué les fautes ?"),("A","Oui, je les ai corrigées."),("B","Merci, elles sont maintenant prêtes.")],"A: I saw the letters you sent. B: Did you notice the mistakes? A: Yes, I corrected them. B: Thanks, they are ready now.")],
"pronunciation":["The auxiliary is often unstressed in connected speech, but keep the participle clearly audible.","The agreement endings -e and -s are usually silent; agreement is mainly visible in writing.","Do not pronounce every final consonant in participles; check the word's standard pronunciation."],
"exercises":[("Choose the correct auxiliary: Elle ___ arrivée.",["a","est","ont","avait"],1,"Arriver commonly uses être in the passé composé."),("Choose the correct agreement: Elles sont ___ tôt.",["parti","partis","partie","parties"],3,"Être participles agree with a feminine plural subject."),("Which sentence has no agreement with avoir?",["Les lettres que j'ai écrites","Je les ai écrites","J'ai écrit les lettres","Les chansons que j'ai chantées"],2,"The direct object follows the verb in J'ai écrit les lettres."),("Complete: Les clés que tu as ___ sont ici.",["trouvé","trouvée","trouvés","trouvées"],3,"Que refers to feminine plural clés and precedes the verb."),("Choose the correct form: Elle s'est ___ les mains.",["lavée","lavés","lavé","lavées"],2,"Les mains is the direct object after the verb; lavé does not agree."),("Which object can trigger agreement with avoir?",["a preceding direct object","any subject","an indirect object after à","an adverb"],0,"Only a preceding direct object triggers the standard agreement rule.")],
"speaking":["Explain the difference between J'ai sorti la voiture and Je suis sorti.","Create six passé composé sentences with être verbs and say the subject agreement aloud.","Describe a sequence of actions using avoir verbs and a preceding direct object pronoun.","Read the dialogues and identify every auxiliary and participle."],
"summary":["Avoir is the auxiliary for most compound-tense verbs.","Être participles agree with the subject.","With avoir, agreement occurs with a preceding direct object.","Reflexive verbs require attention to direct-object roles; do not apply one blanket rule."],
"homework":["Write twelve passé composé sentences, including six être verbs.","Rewrite four sentences with a preceding direct object pronoun and apply agreement.","Explain why lavé remains unchanged in Elle s'est lavé les mains.","Proofread a short past-tense paragraph for auxiliaries and agreements."]
},
96: {
"level":"B1 – Intermediate","title":"Integrated Reading, Listening and Writing Strategies","goal":"Use practical strategies to understand authentic texts and speech, take notes and produce connected written French.",
"objectives":["Identify the main idea, supporting details and speaker purpose.","Use context, cognates and morphology to infer unfamiliar words.","Recognise connected speech, reductions and discourse markers.","Write a coherent paragraph with a clear sequence and basic cohesion."],
"vocab":[("le titre","headline; title","luh tee-truh","/lə titʁ/","Le titre résume le sujet."),("le paragraphe","paragraph","luh pah-rah-grahf","/lə pa.ʁa.ɡʁaf/","Chaque paragraphe développe une idée."),("l'idée principale","main idea","lee-day prahn-see-pal","/li.de pʁɛ̃.si.pal/","Quelle est l'idée principale ?"),("un détail","detail","uhn day-tie","/œ̃ de.taj/","Ce détail confirme l'information."),("un indice","clue; cue","uhn an-dees","/œ̃ ɛ̃.dis/","Le contexte donne un indice."),("le locuteur","speaker","luh loh-kü-tuhr","/lə lɔ.ky.tœʁ/","Le locuteur exprime son opinion."),("un résumé","summary","uhn ray-zü-may","/œ̃ ʁe.zy.me/","Écris un résumé court."),("un brouillon","draft","uhn broo-yohn","/œ̃ bʁu.jɔ̃/","Relis ton brouillon avant de le rendre.")],
"grammar":[("Read for purpose before details","First identify the genre, title, source, audience and purpose. A news report, personal message and opinion column organise information differently. Read once for the global meaning before looking up individual words."),("Infer meaning from context","Use surrounding words, word families, prefixes, suffixes and cognates. French -tion often corresponds to English -tion, but false friends such as actuellement (currently) and éventuellement (possibly) require caution."),("Listening in passes","First listen for topic, participants, setting and overall position. On a second pass, note names, numbers, contrasts, reasons and conclusions. Do not try to translate every word while listening."),("Connected speech and discourse markers","Recognise common reductions and links in speech, and listen for markers such as alors, donc, pourtant, en fait, d'abord and finalement. These signal sequence, consequence, contrast or clarification."),("Paragraph construction","A clear paragraph has a topic sentence, supporting explanation or evidence, and a closing or linking sentence. Use connectors deliberately and maintain consistent tense and pronoun reference.")],
"expressions":[("En résumé,…","In summary,…","Signals a concise synthesis."),("D'après le texte,…","According to the text,…","Introduces source-based information."),("En revanche,…","On the other hand / by contrast,…","Introduces a contrast."),("L'auteur souligne que…","The author emphasises that…","Useful when reporting an author's main point.")],
"examples":[("D'après le titre, l'article porte sur les transports publics.","According to the title, the article is about public transport.","Use context and title to predict subject matter."),("L'auteur présente deux avantages, puis une limite.","The author presents two advantages, then a limitation.","Puis signals sequence."),("En revanche, les participants ne sont pas tous d'accord.","By contrast, the participants do not all agree.","En revanche signals contrast."),("En résumé, le projet est utile, mais son coût reste élevé.","In summary, the project is useful, but its cost remains high.","The summary retains both the positive point and qualification.")],
"conversations":[("Comparing notes after listening",[("A","Qu'as-tu compris de l'entrevue ?"),("B","L'idée principale est que le transport doit devenir plus accessible."),("A","Et quel argument donne l'invitée ?"),("B","Elle explique que les horaires actuels ne répondent pas aux besoins de tous.")],"A: What did you understand from the interview? B: The main idea is that transport must become more accessible. A: And what argument does the guest give? B: She explains that current schedules do not meet everyone's needs."),("Planning a short article",[("A","Quel est ton sujet ?"),("B","Les avantages du vélo en ville."),("A","Commence par ton idée principale, puis donne deux exemples."),("B","Et je termine par une conclusion ?"),("A","Exactement.")],"A: What is your topic? B: The advantages of cycling in the city. A: Start with your main idea, then give two examples. B: And I finish with a conclusion? A: Exactly.")],
"pronunciation":["Listen for syllable groups rather than isolated words; French rhythm groups words into phrases.","Common reductions in informal speech can obscure word boundaries; use context and repeated listening.","Notice contrastive stress and intonation around mais, pourtant and en revanche."],
"exercises":[("What should you identify on the first reading?",["Every unknown word","The text's general purpose and main idea","Only verb endings","The final punctuation"],1,"A global first reading helps establish context before detail work."),("Which is a false friend meaning 'currently'?",["actuellement","éventuellement","actuellement means possibly","actually"],0,"Actuellement means currently; éventuellement means possibly."),("Which connector signals contrast?",["donc","puis","en revanche","d'abord"],2,"En revanche introduces contrast."),("What is a useful second-listening task?",["Translate every syllable","Note reasons, contrasts and key details","Ignore speaker changes","Read a different text"],1,"A second pass should target key information and structure."),("Which is a strong paragraph structure?",["Examples only","Topic sentence, support, closing/link","Unrelated sentences","A list of translations"],1,"A paragraph develops one controlling idea with support."),("Which phrase attributes an idea to a source?",["À mon avis seulement","D'après le texte","Sans raison","À demain"],1,"D'après le texte means according to the text.")],
"speaking":["Listen to a short French clip twice: summarise the main idea, then list five supporting details.","Read a short article and identify its purpose, audience, claim and evidence.","Give a one-minute spoken summary using en résumé and en revanche.","Write one paragraph with a topic sentence, two supports and a closing sentence."],
"summary":["Read and listen for global meaning before analysing details.","Use context and word families, while checking false friends.","Listen in multiple passes and note discourse markers.","Write coherent paragraphs with one main idea and supporting details."],
"homework":["Choose a short French news item and write a 100-word English or simple-French summary.","Create a vocabulary list of ten words inferred from context, then verify them.","Write a 120-word French paragraph with at least five logical connectors.","Listen again and note which words were difficult because of connected speech."]
},
97: {
"level":"B2 – Upper Intermediate","title":"Past Subjunctive and Advanced Mood Selection","goal":"Use the past subjunctive and choose between indicative, subjunctive and infinitive structures with greater precision.",
"objectives":["Form the passé du subjonctif with avoir or être in the subjunctive.","Use it for completed actions after expressions requiring the subjunctive.","Distinguish certainty, emotion, doubt, concession and evaluation.","Avoid common mood errors after conjunctions and impersonal expressions."],
"vocab":[("bien que","although","byan kuh","/bjɛ̃ kə/","Bien qu'il ait terminé, il attend."),("quoique","although; even though","kwah kuh","/kwa kə/","Quoiqu'elle soit partie, nous continuons."),("regretter","to regret","ruh-greh-tay","/ʁə.ɡʁe.te/","Je regrette qu'il soit parti."),("douter","to doubt","doo-tay","/du.te/","Je doute qu'elle ait compris."),("achever","to complete","ah-shuh-vay","/a.ʃə.ve/","Il faut qu'ils aient achevé le travail."),("se rendre","to go; to make one's way","suh rahndr","/sə ʁɑ̃dʁ/","Je suis heureux qu'elle se soit rendue disponible."),("une éventualité","a possibility","ün ay-vahn-tü-ah-lee-tay","/yn e.vɑ̃.ty.a.li.te/","Il faut envisager cette éventualité."),("une réserve","a reservation; qualification","ün ruh-zehrv","/yn ʁə.zɛʁv/","Je formule une réserve.")],
"grammar":[("Forming the past subjunctive","Use the present subjunctive of avoir or être + past participle: que j'aie terminé, qu'elle soit venue, qu'ils aient compris. The past subjunctive marks an action completed before the main clause's reference point."),("When to use it","Use it after a trigger that requires the subjunctive when the subordinate action is already completed: Je suis heureux que tu aies réussi; Je regrette qu'elle soit partie. The trigger determines the mood; the time relationship determines present or past subjunctive."),("Indicative, subjunctive or infinitive","Certainty and reported fact often take the indicative (Je sais qu'il est venu). Doubt, emotion, necessity and certain evaluations take the subjunctive (Je doute qu'il soit venu). When the subject is shared, an infinitive may be more natural: Je suis heureux d'être venu."),("Conjunctions and mood","Bien que and quoique take the subjunctive. Après que normally takes the indicative in standard usage, even though speakers sometimes use the subjunctive by analogy. Avant que takes the subjunctive; the ne explétif may appear in formal style but is not negative."),("Agreement and register","Past participle agreement follows the same auxiliary principles used in compound tenses: être participles agree with the subject; avoir agreement depends on a preceding direct object. In careful writing, keep the mood and tense sequence clear.")],
"expressions":[("Je suis ravi que tu aies pu venir.","I'm delighted you were able to come.","Emotion trigger + completed subordinate action."),("Je doute qu'ils aient reçu le message.","I doubt they received the message.","Douter que triggers the subjunctive."),("Bien qu'elle soit arrivée tard,…","Although she arrived late,…","Concession with past subjunctive."),("Après qu'il est parti,…","After he left,…","Après que normally takes the indicative.")],
"examples":[("Je suis surpris qu'ils aient accepté notre proposition.","I am surprised that they accepted our proposal.","Emotion + completed action; past subjunctive of accepter."),("Elle regrette que son collègue soit parti sans prévenir.","She regrets that her colleague left without warning.","Regret triggers subjunctive; être auxiliary participle agrees with masculine singular subject."),("Je sais qu'il a terminé le rapport.","I know he finished the report.","Savoir que expresses certainty and takes indicative."),("Bien que nous ayons reçu les documents, il manque une signature.","Although we received the documents, a signature is missing.","Bien que requires subjunctive; avoir subjunctive + reçu."),("Après qu'elle a présenté les résultats, le comité a posé des questions.","After she presented the results, the committee asked questions.","Après que normally takes indicative.")],
"conversations":[("Responding to a completed event",[("A","Je suis étonné que vous ayez terminé si vite."),("B","Nous avions commencé plus tôt que prévu."),("A","Je suis content que tout se soit bien passé."),("B","Merci. Nous sommes heureux que le résultat vous convienne.")],"A: I'm surprised you finished so quickly. B: We had started earlier than expected. A: I'm glad everything went well. B: Thank you. We're happy the result suits you."),("Discussing a report",[("A","Je doute que l'équipe ait vérifié toutes les données."),("B","Pourtant, elle affirme qu'elle les a contrôlées."),("A","Après qu'elle a terminé l'analyse, nous examinerons les conclusions."),("B","D'accord, nous attendrons le rapport final.")],"A: I doubt the team checked all the data. B: Yet it says it checked them. A: After it finishes the analysis, we'll examine the conclusions. B: All right, we'll wait for the final report.")],
"pronunciation":["Aie and aient are pronounced alike in many contexts; distinguish them through grammar and subject agreement.","The subjunctive endings are often less audible than spelling suggests; practise whole verb groups.","Do not add a pause that separates bien que from its subordinate clause."],
"exercises":[("Complete: Je suis heureux que tu ___ réussi.",["as","aies","avais","auras"],1,"Emotion requires the subjunctive; completed action uses aies réussi."),("Complete: Je sais qu'elle ___ venue.",["soit","est","ait","vienne"],1,"Savoir que expresses certainty and takes the indicative."),("Which conjunction normally takes the indicative?",["bien que","avant que","après que","quoique"],2,"Après que normally takes the indicative."),("Complete: Je regrette qu'il ___ parti.",["a","ait","soit","est"],2,"Partir takes être; past subjunctive is soit parti."),("Which sentence uses a shared-subject infinitive naturally?",["Je suis heureux que je sois venu.","Je suis heureux d'être venu.","Je sais que venir.","Je doute d'il vient."],1,"A shared subject commonly allows de + infinitive."),("What does ne explétif do after avant que?",["Negates the verb","Adds formal style without negation","Changes subjunctive to indicative","Marks past tense"],1,"Ne explétif is not negative.")],
"speaking":["Explain why the indicative or subjunctive is used in eight example clauses.","Create five past-subjunctive sentences with emotion, doubt or concession triggers.","Contrast bien que, avant que and après que in original sentences.","Summarise a completed event while distinguishing what is known from what is uncertain."],
"summary":["Past subjunctive = present subjunctive of avoir/être + past participle.","Use it for completed subordinate actions after subjunctive triggers.","Mood depends on the governing expression; tense depends on time relationship.","Après que normally takes the indicative; ne explétif is not negative."],
"homework":["Write ten sentences using the past subjunctive and label each trigger.","Write five indicative/subjunctive contrasts and explain the meaning difference.","Edit a paragraph for mood selection and participle agreement.","Prepare a two-minute explanation of one recent event using concession and emotion clauses."]
},
98: {
"level":"B2 – Upper Intermediate","title":"Word Formation, Collocations and Register","goal":"Expand vocabulary efficiently by recognising word families, selecting natural word partnerships and adapting register.",
"objectives":["Recognise common prefixes, suffixes and word-family patterns.","Choose verbs, nouns and adjectives that naturally collocate.","Distinguish formal, neutral and informal vocabulary.","Avoid literal translation and common false friends."],
"vocab":[("une démarche","process; approach","ün day-marsh","/yn de.maʁʃ/","Entreprendre une démarche administrative."),("mettre en œuvre","to implement","meh-trahn-oevr","/mɛtʁ ɑ̃ nœvʁ/","Mettre en œuvre une stratégie."),("prendre une décision","to make a decision","prahn-druh ün day-see-zyohn","/pʁɑ̃dʁ yn de.si.zjɔ̃/","Prendre une décision importante."),("un enjeu","an issue; stake","uhn ahn-zhuh","/œ̃n ɑ̃.ʒø/","Les enjeux sont considérables."),("fiable","reliable","fee-ahbl","/fjabl/","Une source fiable."),("pertinent","relevant","pehr-tee-nahn","/pɛʁ.ti.nɑ̃/","Une remarque pertinente."),("approfondir","to explore in depth","ah-proh-fohn-deer","/a.pʁɔ.fɔ̃.diʁ/","Approfondir une question."),("un malentendu","a misunderstanding","uhn mahl-ahn-tahn-dü","/œ̃ mal.ɑ̃.tɑ̃.dy/","Éviter un malentendu.")],
"grammar":[("Word families","Recognise roots and related forms: décider (verb), décision (noun), décisif/décisive (adjective). Prefixes and suffixes can help infer meaning, but spelling and gender may change."),("Common prefixes and suffixes","Prefixes such as re- (again), dé-/dés- (undo/reverse), pré- (before) and suffixes such as -tion, -ment, -able and -ité form useful patterns. Learn each new word in a sentence and verify whether the pattern is productive."),("Collocations","French words form conventional partnerships: prendre une décision, poser une question, commettre une erreur, mener une enquête, fortement recommandé. A grammatically possible phrase may still sound unnatural if the collocation is wrong."),("Register and audience","Choose vocabulary for the situation: boulot is informal for work, travail is neutral, emploi can mean employment/job. In formal writing, prefer precise standard terms; in conversation, informal forms may be appropriate with familiar people."),("False friends and semantic range","Check meaning in context: assister à means attend; demander means ask; librairie is a bookshop; sensible means sensitive. A dictionary entry may have several senses, so learn the phrase and its collocates.")],
"expressions":[("prendre en compte","to take into account","Common in neutral and formal communication."),("jouer un rôle","to play a role","Natural collocation with rôle."),("soulever une question","to raise an issue","Useful in meetings and writing."),("à la suite de","following; as a result of","Formal connector; exact meaning depends on context.")],
"examples":[("Cette décision aura des conséquences importantes.","This decision will have important consequences.","A natural collocation is avoir des conséquences."),("Il faut prendre en compte les besoins des utilisateurs.","We must take users' needs into account.","Prendre en compte is a fixed verbal expression."),("La proposition est pertinente, mais elle doit être approfondie.","The proposal is relevant, but it needs to be explored further.","Pertinent and approfondir fit analytical contexts."),("À la suite de la réunion, un plan a été mis en œuvre.","Following the meeting, a plan was implemented.","Formal sequence expression and passive construction.")],
"conversations":[("Choosing the right register",[("A","Tu as du boulot cette semaine ?"),("B","Oui, j'ai beaucoup de travail à terminer."),("A","C'est pour le projet dont tu m'as parlé ?"),("B","Exactement. Je dois mettre en œuvre la nouvelle stratégie.")],"A: Do you have a lot of work this week? B: Yes, I have a lot of work to finish. A: Is it for the project you told me about? B: Exactly. I have to implement the new strategy."),("Improving a phrase",[("A","J'ai fait une décision importante."),("B","On dit plutôt « prendre une décision »."),("A","Merci. Et « poser une question » ?"),("B","Oui, c'est la collocation naturelle.")],"A: I made an important decision (literal translation). B: We say rather 'take a decision'. A: Thanks. And 'ask a question'? B: Yes, that's the natural collocation.")],
"pronunciation":["Many suffixes have predictable stress patterns, but practise complete words rather than reading letter by letter.","In collocations, link words smoothly; do not over-stress every content word equally.","Notice silent final consonants in words such as beaucoup and souvent, and check exceptions individually."],
"exercises":[("Which is the natural collocation?",["faire une décision","prendre une décision","poser une décision","mettre une décision"],1,"French uses prendre une décision."),("What does assister à mean?",["to help someone","to attend an event","to insist","to assist physically"],1,"Assister à means attend."),("Which word is most informal?",["travail","emploi","boulot","profession"],2,"Boulot is informal for work."),("Which phrase means 'to take into account'?",["prendre en compte","prendre en place","poser en compte","mettre en compte"],0,"Prendre en compte is the standard expression."),("Which word family is correct?",["décider – décision – décisif","décider – décidation – décisité","décision – décidoir – décideux","décider – décidement – décidable"],0,"Décider, décision and décisif are related forms."),("Which phrase means 'to raise an issue'?",["soulever une question","lever une réponse","poser un problème à haut","faire une question"],0,"Soulever une question is a natural collocation.")],
"speaking":["Choose ten verbs and build a natural noun or adjective collocation for each.","Explain the difference between a formal, neutral and informal way to say 'work'.","Correct five literal translations and explain the natural French collocation.","Summarise a workplace issue using at least six precise word partnerships."],
"summary":["Word families help expand vocabulary, but forms must be checked.","Collocations are conventional word partnerships and are essential for naturalness.","Register depends on audience, purpose and context.","False friends require context-based learning rather than word-for-word translation."],
"homework":["Create a word-family notebook with twelve roots and related forms.","Record twenty useful collocations with example sentences.","Rewrite a casual message in neutral and formal French.","Check five false friends in a reliable dictionary and write contextual examples."]
},
99: {
"level":"C1 – Advanced","title":"Critical Listening, Note-Taking and Media Analysis","goal":"Interpret complex spoken French, distinguish fact from opinion and synthesise information from interviews, debates and media.",
"objectives":["Identify thesis, evidence, stance, tone and implied assumptions.","Recognise hedging, reformulation, irony and discourse markers.","Take structured notes without transcribing every word.","Compare speakers and produce a balanced synthesis."],
"vocab":[("une thèse","thesis; central claim","ün tez","/yn tɛz/","La thèse est clairement formulée."),("un présupposé","an assumption","uhn pray-sü-poh-zay","/œ̃ pʁe.sy.po.ze/","Cet argument repose sur un présupposé."),("une nuance","a nuance","ün nü-ahns","/yn nɥɑ̃s/","Il faut apporter une nuance."),("un témoignage","a testimony","uhn tay-mwah-nyazh","/œ̃ te.mwa.ɲaʒ/","Le témoignage apporte un éclairage."),("une source","a source","ün soors","/yn suʁs/","Vérifiez la fiabilité de la source."),("un biais","a bias","uhn bay","/œ̃ bɛ/","L'analyse doit tenir compte du biais."),("étayer","to support with evidence","ay-tay-yay","/e.te.je/","Les chiffres étayent l'argument."),("nuancer","to qualify; add nuance","nü-ahn-say","/nɥɑ̃.se/","L'intervenante nuance son propos.")],
"grammar":[("Separate claim from evidence","A speaker may present a claim, an example, a statistic and an interpretation. Label them separately in notes. A vivid anecdote is not automatically representative evidence."),("Hedging and degrees of certainty","Expressions such as il semblerait que, dans une certaine mesure, probablement and rien ne permet d'affirmer que qualify certainty. Preserve these qualifications when summarising; do not turn a cautious claim into a fact."),("Reported stance and attribution","Use selon l'intervenant, l'autrice soutient que, il estime que and le rapport indique que to attribute views. Distinguish the speaker's position from your own evaluation."),("Reformulation and discourse markers","Autrement dit, en d'autres termes, cela dit, or encore faut-il signal a restatement, qualification or limitation. These markers often reveal the structure of a long argument."),("Synthesis across sources","A synthesis groups information by theme rather than summarising each source separately. Use convergences, differences and unresolved questions; cite or attribute each viewpoint clearly.")],
"expressions":[("Il convient toutefois de nuancer…","It is nevertheless necessary to qualify…","Formal and analytical."),("Rien ne permet d'affirmer que…","Nothing allows us to claim that…","Useful for limiting an inference."),("Les données tendent à montrer que…","The data tend to show that…","Hedged evidence statement."),("Cela dit,…","That said,…","Introduces a qualification or counterpoint.")],
"examples":[("L'intervenante avance trois arguments, tout en reconnaissant certaines limites.","The speaker puts forward three arguments while acknowledging certain limitations.","Tout en + present participle marks simultaneous concession."),("Les données tendent à montrer une évolution, sans en établir la cause.","The data tend to show a change without establishing its cause.","Preserve the distinction between correlation and causation."),("Selon le rapport, les résultats restent préliminaires.","According to the report, the results remain preliminary.","Attribution prevents presenting a source's claim as your own fact."),("Cela dit, cette conclusion mérite d'être nuancée.","That said, this conclusion deserves to be qualified.","Cela dit signals a counterpoint.")],
"conversations":[("Analysing an interview",[("A","Quelle est la thèse défendue par l'invitée ?"),("B","Elle soutient que la réforme pourrait améliorer l'accès aux services."),("A","Est-ce qu'elle présente des preuves ?"),("B","Oui, mais elle précise que les données restent préliminaires.")],"A: What thesis does the guest defend? B: She argues that the reform could improve access to services. A: Does she present evidence? B: Yes, but she specifies that the data remain preliminary."),("Comparing two sources",[("A","Les deux articles arrivent-ils à la même conclusion ?"),("B","Pas tout à fait. Ils reconnaissent le même problème, mais proposent des solutions différentes."),("A","Il faudrait donc comparer leurs présupposés."),("B","Exactement, et vérifier les sources citées.")],"A: Do the two articles reach the same conclusion? B: Not exactly. They recognise the same problem but propose different solutions. A: So we should compare their assumptions. B: Exactly, and check the cited sources.")],
"pronunciation":["In fast speech, discourse markers may be reduced; learn their sound shape in complete phrases.","Listen for intonation that signals doubt, irony, concession or a speaker's shift in stance.","Note phrase groups and pauses; a pause can separate a claim from its qualification."],
"exercises":[("What should a synthesis organise?",["Each source in isolation","Ideas by shared themes and contrasts","Only quotations","The listener's assumptions"],1,"A synthesis groups information by theme across sources."),("Which expression hedges certainty?",["Il est absolument certain que","Il semblerait que","Cela prouve définitivement que","Sans aucun doute"],1,"Il semblerait que expresses a cautious inference."),("Why attribute a claim?",["To make it sound stronger","To distinguish the source's position from your own","To avoid understanding it","To remove evidence"],1,"Attribution makes the origin of a viewpoint clear."),("Which is evidence rather than a claim?",["A speaker's conclusion","A verified survey result","A rhetorical question","A prediction without support"],1,"A verified survey result is evidence, though its limits still need analysis."),("Which marker introduces a qualification?",["Cela dit","Premièrement only","En conclusion only","À demain"],0,"Cela dit introduces a qualification or counterpoint."),("What should notes capture first?",["Every word","Thesis, reasons, evidence and stance","Only unfamiliar vocabulary","Every hesitation"],1,"Structured notes capture the argument rather than a transcript.")],
"speaking":["Listen to a 3–5 minute interview and produce a structured outline of thesis, evidence and qualifications.","Compare two short articles on one issue and deliver a balanced synthesis.","Explain which claims are supported, uncertain or merely asserted.","Give a two-minute oral summary that preserves the speaker's degree of certainty."],
"summary":["Critical listening distinguishes thesis, evidence, stance and assumptions.","Hedging and qualification must survive an accurate summary.","Attribution separates source claims from personal judgement.","A synthesis organises ideas across sources rather than repeating each source separately."],
"homework":["Choose two French-language media sources on one issue and compare their claims.","Create structured notes with claim/evidence/qualification columns.","Write a 250-word synthesis with clear attribution and balanced treatment.","Review the audio and identify three reductions or discourse markers you initially missed."]
},
100: {
"level":"C1 – Advanced","title":"Academic Reading, Synthesis and Referencing","goal":"Read demanding academic and literary non-fiction, evaluate arguments and produce coherent evidence-based synthesis.",
"objectives":["Analyse structure, thesis, evidence and counterargument.","Interpret nominalisation, dense noun phrases and complex connectors.","Paraphrase accurately without distorting meaning.","Integrate sources and distinguish quotation, paraphrase and personal analysis."],
"vocab":[("une problématique","research question; problem framework","ün proh-blay-mah-teek","/yn pʁɔ.ble.ma.tik/","La problématique guide l'étude."),("un corpus","a body of texts/data","uhn kohr-püs","/œ̃ kɔʁ.pys/","Le corpus comprend plusieurs articles."),("une hypothèse","a hypothesis","ün ee-poh-tehz","/yn i.po.tɛz/","L'hypothèse doit être vérifiée."),("un argument","an argument","uhn ar-gü-mahn","/œ̃n aʁ.ɡy.mɑ̃/","L'argument repose sur des données."),("une source primaire","a primary source","ün soors pree-mair","/yn suʁs pʁi.mɛʁ/","Une lettre peut être une source primaire."),("une citation","a quotation/citation","ün see-tah-syohn","/yn si.ta.sjɔ̃/","La citation doit être attribuée."),("paraphraser","to paraphrase","pah-rah-frah-zay","/pa.ʁa.fʁa.ze/","Il faut paraphraser avec précision."),("une synthèse","a synthesis","ün san-tehz","/yn sɛ̃.tɛz/","La synthèse met les idées en relation.")],
"grammar":[("Dense noun phrases","Academic French often compresses information into noun phrases: la mise en œuvre de la politique publique. Unpack the phrase into agent, action and affected object to understand it; use nominalisation selectively in formal writing."),("Logical relations in complex prose","Connectors such as dans la mesure où, dès lors que, tandis que, en dépit de and faute de encode cause, condition, contrast and concession. Identify the exact relation before translating or paraphrasing."),("Paraphrase without distortion","Change structure and vocabulary while preserving scope, certainty, attribution and causal relationships. A paraphrase must not strengthen a cautious claim or remove a limitation."),("Integrating sources","Introduce the source, present its relevant claim, explain its relevance and connect it to your analysis. Use quotation for exact wording; paraphrase for ideas. Attribute both."),("Academic argument structure","A strong argument states a problem, defines terms, develops claims with evidence, considers counterarguments and reaches a proportionate conclusion. Avoid unsupported generalisations and overclaiming.")],
"expressions":[("Dans la mesure où…","To the extent that / insofar as…","Introduces a qualified relation or condition."),("Il ressort de cette analyse que…","It emerges from this analysis that…","Formal synthesis phrase."),("Cette interprétation mérite d'être nuancée.","This interpretation deserves qualification.","Signals critical distance."),("Les résultats ne sauraient être généralisés.","The results cannot be generalised.","Formal caution about scope.")],
"examples":[("Il ressort de l'analyse que les résultats varient selon le contexte.","It emerges from the analysis that results vary according to context.","Formal impersonal synthesis."),("Dans la mesure où l'échantillon est limité, les conclusions doivent rester prudentes.","Since the sample is limited, conclusions must remain cautious.","The connector signals a qualified reason."),("L'autrice souligne cette limite, ce qui invite à nuancer l'interprétation.","The author highlights this limitation, which invites a more nuanced interpretation.","Relative clause links evidence to analysis."),("Plutôt que de reprendre la formulation originale, le chercheur en reformule l'idée centrale.","Rather than repeating the original wording, the researcher reformulates its central idea.","En refers to the idea introduced by de.")],
"conversations":[("Discussing a source",[("A","Quelle est la contribution principale de cet article ?"),("B","Il montre que les résultats dépendent fortement du contexte."),("A","Peut-on généraliser cette conclusion ?"),("B","Pas sans tenir compte des limites du corpus.")],"A: What is the main contribution of this article? B: It shows that results depend strongly on context. A: Can this conclusion be generalised? B: Not without taking the corpus limitations into account."),("Preparing a synthesis",[("A","Comment vas-tu organiser ta synthèse ?"),("B","Je vais regrouper les arguments par thème, puis comparer les sources."),("A","Et les citations ?"),("B","Je vais les attribuer clairement et distinguer les paraphrases de mon analyse.")],"A: How will you organise your synthesis? B: I'll group arguments by theme, then compare the sources. A: And the quotations? B: I'll attribute them clearly and distinguish paraphrases from my analysis.")],
"pronunciation":["Academic words often contain several syllables; practise stress groups and liaison in full phrases.","Do not let long noun phrases become flat: group them into meaningful chunks.","Distinguish connector sounds carefully, especially tandis que, dans la mesure où and dès lors que."],
"exercises":[("What must a faithful paraphrase preserve?",["Only the topic","Meaning, scope, certainty and attribution","The original word order","The writer's opinion instead"],1,"A paraphrase preserves the original claim's limits and source."),("Which phrase expresses a qualified relation?",["Dans la mesure où","À demain","Tout à fait","Jamais de la vie"],0,"Dans la mesure où introduces a qualified relation or condition."),("What is a primary source?",["A later summary only","An original document or first-hand record","Any opinion online","A dictionary definition"],1,"A primary source is an original or first-hand source."),("Which is an appropriate academic conclusion?",["The evidence proves everything","The findings suggest X within the limits of the corpus","Everyone knows X","No further questions exist"],1,"Academic conclusions should be proportionate to evidence."),("Why attribute a paraphrase?",["Only quotations need attribution","Ideas from sources still require attribution","Attribution weakens the argument","It is optional in academic work"],1,"Paraphrased ideas still belong to their source."),("What is nominalisation?",["Turning a noun into a verb only","Expressing an action or quality as a noun","Removing all nouns","Using informal slang"],1,"Nominalisation packages an action or quality as a noun.")],
"speaking":["Present an academic article's thesis, method, evidence and limitation in three minutes.","Paraphrase a dense paragraph orally without strengthening its claims.","Compare two sources and explain where they agree, differ or leave questions open.","Defend a conclusion while clearly stating the limits of the evidence."],
"summary":["Academic reading requires analysis of argument structure and evidence.","Dense noun phrases can be unpacked into agents, actions and objects.","Paraphrasing must preserve scope, certainty and attribution.","A synthesis connects sources by theme and supports proportionate conclusions."],
"homework":["Read a French-language essay or report and map its thesis, evidence and counterargument.","Write a 250–300 word synthesis of two sources with attribution.","Paraphrase one difficult paragraph and compare it with the original for meaning drift.","Create a glossary of fifteen academic collocations from your reading."]
},
101: {
"level":"C2 – Mastery","title":"Mediation, Paraphrasing and Precision Across Registers","goal":"Transfer complex information accurately between audiences, registers and communication formats without losing nuance.",
"objectives":["Summarise complex material for a different audience.","Paraphrase idioms and culturally bound references appropriately.","Preserve uncertainty, stance, humour and interpersonal intent.","Reformulate spoken and written content clearly and ethically."],
"vocab":[("reformuler","to rephrase","ruh-fohr-mü-lay","/ʁə.fɔʁ.my.le/","Il faut reformuler sans déformer le sens."),("une nuance","a nuance","ün nü-ahns","/yn nɥɑ̃s/","Cette nuance est essentielle."),("un sous-entendu","an implication; subtext","uhn soo-zahn-tahn-dü","/œ̃ su.zɑ̃.tɑ̃.dy/","Le sous-entendu dépend du contexte."),("un équivalent","an equivalent","uhn ay-kee-vah-lahn","/œ̃n e.ki.va.lɑ̃/","Il n'existe pas toujours d'équivalent exact."),("un destinataire","recipient; intended audience","uhn dehs-tee-nah-tair","/œ̃ dɛs.ti.na.tɛʁ/","Adaptez le message au destinataire."),("une ambiguïté","an ambiguity","ün ahm-bee-gü-ee-tay","/yn ɑ̃.bi.ɡɥi.te/","Il faut préserver l'ambiguïté voulue."),("atténuer","to soften; mitigate","ah-tay-nü-ay","/a.te.nɥe/","Cette formule atténue la critique."),("expliciter","to make explicit","ehks-plee-see-tay","/ɛks.pli.si.te/","Il convient d'expliciter la référence.")],
"grammar":[("Audience-aware reformulation","Choose what to explain, omit or retain based on the recipient's knowledge and purpose. A specialist summary can preserve technical terms; a public-facing version may need definitions and examples."),("Preserving modality and uncertainty","Maintain distinctions such as possible, probable, necessary and certain. Ne transforme pas pourrait into will; semblerait does not mean proves. Precision includes preserving what the source does not claim."),("Idioms and cultural references","Do not translate idioms word for word when they would confuse the recipient. Explain the meaning, choose a functional equivalent or retain the original with a brief gloss when the cultural form matters."),("Register shifts","Move between formal, neutral and informal French while preserving intent. A direct imperative may become a softened request; a colloquial expression may need a neutral paraphrase for a professional audience."),("Ethical mediation","Represent the speaker fairly, distinguish quotation from interpretation, protect confidential details and avoid adding claims. If a phrase is ambiguous, signal the ambiguity instead of inventing certainty.")],
"expressions":[("Autrement dit,…","In other words,…","Signals reformulation."),("Pour être plus précis,…","To be more precise,…","Introduces a clarification."),("Il convient de préciser que…","It should be specified that…","Formal qualification."),("L'expression renvoie à…","The expression refers to…","Explains a cultural or idiomatic reference.")],
"examples":[("Autrement dit, la mesure pourrait être utile, sans que son efficacité soit encore démontrée.","In other words, the measure could be useful, although its effectiveness has not yet been demonstrated.","Preserves possibility and lack of proof."),("Pour un public non spécialiste, il faudrait expliciter le terme technique.","For a non-specialist audience, the technical term would need to be explained.","Audience determines the level of explanation."),("L'expression est ironique; une traduction littérale ferait perdre le sous-entendu.","The expression is ironic; a literal translation would lose the implication.","Meaning includes pragmatic intent, not just words."),("La critique a été atténuée afin de préserver une relation professionnelle.","The criticism was softened to preserve a professional relationship.","Register adjustment changes force while retaining the point.")],
"conversations":[("Mediating a disagreement",[("A","Il a dit que le projet était irréalisable."),("B","Le ton était plus nuancé : il a dit qu'il serait difficile à réaliser dans les délais."),("A","Donc, il ne rejetait pas le projet lui-même ?"),("B","Exactement. Il mettait surtout en doute le calendrier.")],"A: He said the project was impossible. B: The tone was more nuanced: he said it would be difficult to complete on schedule. A: So he wasn't rejecting the project itself? B: Exactly. He was mainly questioning the timeline."),("Explaining an idiom",[("A","Que signifie cette expression québécoise ?"),("B","Elle exprime une lassitude; il ne faut pas la traduire mot à mot."),("A","Comment l'expliquerais-tu à un collègue ?"),("B","Je donnerais le sens, le registre et une expression neutre équivalente.")],"A: What does this Quebec expression mean? B: It expresses frustration; it should not be translated word for word. A: How would you explain it to a colleague? B: I'd give the meaning, register and a neutral equivalent.")],
"pronunciation":["Intonation communicates tact, irony and uncertainty; practise the same sentence with different pragmatic intentions.","Preserve hesitation and qualification when they are meaningful rather than smoothing away all nuance.","In reformulation, pause at clause boundaries so the listener can follow the logical structure."],
"exercises":[("What must a mediator preserve?",["Only the literal words","Meaning, stance, uncertainty and relevant intent","Their own preferred conclusion","Every hesitation regardless of purpose"],1,"Accurate mediation preserves meaning and pragmatic force."),("Which paraphrase preserves uncertainty?",["Il pourrait réussir → Il réussira","Il pourrait réussir → Il est possible qu'il réussisse","Il pourrait réussir → Il a réussi","Il pourrait réussir → Il réussit toujours"],1,"The paraphrase retains possibility rather than turning it into certainty."),("What is best for a culturally specific idiom?",["Always translate word for word","Explain its function or provide a contextual equivalent","Delete it without explanation","Invent a similar-sounding phrase"],1,"A functional explanation avoids misleading literal translation."),("Which phrase introduces a clarification?",["Pour être plus précis","À bientôt","Jamais","Peu importe"],0,"Pour être plus précis signals a more exact formulation."),("Why adapt register?",["To change the facts","To fit audience, purpose and relationship","To hide the original meaning","To use more difficult words"],1,"Register is selected for the audience and situation."),("What should you do with genuine ambiguity?",["Invent a definite meaning","Signal and preserve the ambiguity","Ignore the sentence","Replace it with an unrelated claim"],1,"Do not manufacture certainty where the source is ambiguous.")],
"speaking":["Summarise a complex policy for both a specialist and a general audience.","Explain a Quebec or Acadian idiom to someone unfamiliar with the community, including register and context.","Reformulate a blunt criticism as a tactful professional message without hiding the substance.","Paraphrase a nuanced statement while preserving possibility, doubt and qualification."],
"summary":["Mediation transfers meaning between audiences and formats.","Preserve modality, uncertainty, stance and pragmatic intent.","Explain idioms functionally rather than translating them literally.","Adapt register without changing the underlying facts or adding unsupported claims."],
"homework":["Create two versions of a complex explanation: specialist and general-public.","Choose five idioms and explain their meaning, register and closest functional equivalent.","Rewrite a direct complaint as a tactful professional message, preserving the request.","Compare your paraphrase with the source and list any nuance that was lost."]
},
102: {
"level":"C2 – Mastery","title":"Integrated C2 Capstone and Independent Language Portfolio","goal":"Demonstrate integrated mastery through an independent project combining research, comprehension, interaction, writing and reflective self-assessment.",
"objectives":["Plan and complete a substantial French-language project.","Synthesize multiple spoken and written sources with attribution.","Present a nuanced argument and respond spontaneously to questions.","Revise writing and reflect on strengths, gaps and future learning goals."],
"vocab":[("un dossier","a portfolio; case file","uhn doh-see-ay","/œ̃ dɔ.si.e/","Constituer un dossier complet."),("une démarche","an approach; process","ün day-marsh","/yn de.maʁʃ/","Présenter une démarche cohérente."),("une problématique","a central question","ün proh-blay-mah-teek","/yn pʁɔ.ble.ma.tik/","Définir une problématique précise."),("un bilan","an assessment; review","uhn bee-lahn","/œ̃ bi.lɑ̃/","Faire le bilan de son apprentissage."),("une retombée","an outcome; consequence","ün ruh-tohn-bay","/yn ʁə.tɔ̃.be/","Évaluer les retombées du projet."),("un argumentaire","a set of arguments","uhn ar-gü-mahn-tair","/œ̃n aʁ.ɡy.mɑ̃.tɛʁ/","Préparer un argumentaire solide."),("une révision","a revision","ün ray-vee-zyohn","/yn ʁe.vi.zjɔ̃/","La révision améliore la clarté."),("un objectif mesurable","a measurable objective","uhn ohb-zhek-teef muh-zü-rahbl","/œ̃n ɔb.ʒɛk.tif mə.zy.ʁabl/","Fixer un objectif mesurable.")],
"grammar":[("Project proposal and scope","Define a focused question, intended audience, deliverable and evidence base. Use precise future and conditional forms to describe intended outcomes and limitations."),("Synthesis and attribution","Integrate several sources by theme, attribute claims and distinguish evidence from interpretation. Use reported speech and nuanced connectors to show agreement, contrast and qualification."),("Argument and counterargument","State a defensible thesis, support it, acknowledge the strongest counterargument and explain why your conclusion remains proportionate. Avoid absolute claims when the evidence is limited."),("Revision and stylistic control","Edit in passes: structure, argument, paragraph cohesion, grammar, vocabulary, register, spelling and punctuation. Replace vague repetition with precise collocations without making the prose artificially ornate."),("Reflection and self-assessment","Evaluate comprehension, fluency, interaction, accuracy and range using concrete evidence from the project. Set specific next goals rather than relying on a general feeling of confidence.")],
"expressions":[("Cette analyse met en évidence…","This analysis highlights…","Introduces a supported finding."),("Il importe toutefois de rappeler que…","It is nevertheless important to recall that…","Adds a qualification."),("Les éléments recueillis suggèrent que…","The evidence gathered suggests that…","A cautious evidence-based conclusion."),("Au terme de cette démarche,…","At the end of this process,…","Introduces final findings or reflection.")],
"examples":[("Cette analyse met en évidence plusieurs facteurs, sans prétendre épuiser la question.","This analysis highlights several factors without claiming to exhaust the issue.","A nuanced claim states its scope."),("Les éléments recueillis suggèrent une tendance, qui devra être vérifiée à plus grande échelle.","The evidence gathered suggests a trend that will need to be verified on a larger scale.","Preserves uncertainty and future verification."),("Au terme de cette démarche, je retiens trois enseignements principaux.","At the end of this process, I draw three main lessons.","A natural capstone conclusion."),("Il importe toutefois de rappeler que le corpus demeure limité.","It is nevertheless important to recall that the corpus remains limited.","A clear limitation statement.")],
"conversations":[("Project presentation and questions",[("Présentateur","Ma recherche porte sur l'accès aux services en français dans différentes communautés."),("Participant","Comment avez-vous choisi vos sources ?"),("Présentateur","J'ai comparé des rapports, des témoignages et des données publiques."),("Participant","Quelles sont les principales limites ?"),("Présentateur","Le corpus est limité; les résultats doivent donc être interprétés avec prudence.")],"Presenter: My research concerns access to French-language services in different communities. Participant: How did you choose your sources? Presenter: I compared reports, testimonies and public data. Participant: What are the main limitations? Presenter: The corpus is limited; the results must therefore be interpreted cautiously."),("Reflecting on progress",[("A","Quelle compétence as-tu le plus développée ?"),("B","La compréhension orale, surtout lorsque plusieurs personnes prennent la parole."),("A","Et quel sera ton prochain objectif ?"),("B","Améliorer la spontanéité et la précision dans les débats complexes.")],"A: Which skill have you developed the most? B: Listening comprehension, especially when several people speak. A: And what will your next goal be? B: Improving spontaneity and precision in complex debates.")],
"pronunciation":["Practise the presentation with natural phrase groups, varied intonation and clear transitions.","Use pauses to signal structure rather than filling every silence with discourse markers.","Prepare key technical terms, but practise paraphrasing them spontaneously when a listener asks for clarification."],
"exercises":[("What makes a strong capstone question?",["A topic too broad to investigate","A focused, answerable question with a clear scope","A question with a predetermined answer","A list of unrelated facts"],1,"A focused question gives the project a manageable direction."),("What should a synthesis do?",["List sources one by one only","Integrate evidence by themes and attribute claims","Remove disagreements","Treat opinions as facts"],1,"A synthesis connects sources while retaining attribution and differences."),("Which conclusion is appropriately cautious?",["This proves the issue is solved","The evidence suggests a trend within the limits of this sample","Everyone agrees","No further research is possible"],1,"A defensible conclusion reflects the evidence and its limitations."),("Which is the best revision order?",["Punctuation before structure","Structure and argument, then language and proofreading","Only replace words with longer synonyms","Do not revise"],1,"Large-scale structure should be revised before surface editing."),("What is a measurable learning goal?",["Become perfect","Understand everything","Deliver a five-minute presentation with a clear thesis and evidence","Speak better someday"],2,"A measurable goal specifies an observable performance."),("Which phrase introduces a limitation?",["Il importe toutefois de rappeler que","À demain","C'est super","Jamais"],0,"The expression introduces an important qualification.")],
"speaking":["Deliver a five-minute presentation of an independent project, followed by unscripted questions.","Defend your thesis, acknowledge a counterargument and qualify your conclusion.","Summarise two sources orally and explain how their evidence differs.","Complete a spoken self-assessment naming evidence of progress and two measurable next goals."],
"summary":["The capstone integrates comprehension, research, argument, interaction and writing.","A strong project has a focused question, credible sources and transparent limitations.","C2 communication is precise, flexible and audience-aware, not needlessly complicated.","Reflection should lead to measurable next steps for continued development."],
"homework":["Create a portfolio containing a project proposal, source notes, a synthesis and a final written piece.","Prepare and deliver a five-minute presentation with a short question-and-answer session.","Revise the written work in separate passes for structure, argument, register and accuracy.","Write a reflective review with evidence of strengths, remaining gaps and three measurable future goals."]
},
103: {
"level":"A2 – Elementary",
"title":"Contracted Articles, Prepositions and Verb Complements",
"goal":"Use French article contractions and common preposition patterns accurately when describing places, movement and relationships.",
"objectives":["Form au, aux, du and des from à/de plus definite articles.","Distinguish à, de, chez, en and dans in common contexts.","Recognise common verbs followed by à or de.","Use depuis and pendant to describe time relationships."],
"vocab":[("à","to; at","ah","/a/","Je vais à l'école."),("de","of; from","duh","/də/","Je viens de Luanda."),("au","to/at the (masculine)","oh","/o/","Je vais au marché."),("aux","to/at the (plural)","oh","/o/","Elle parle aux étudiants."),("du","of/from the (masculine)","dü","/dy/","La porte du musée est ouverte."),("des","of/from the (plural)","day","/de/","Le nom des rues est affiché."),("chez","at the home/place of","shay","/ʃe/","Je vais chez le médecin."),("depuis","since; for (continuing)","duh-pwee","/də.pɥi/","J'habite ici depuis deux ans.")],
"grammar":[("The four mandatory contractions","À + le becomes au; à + les becomes aux; de + le becomes du; de + les becomes des. Do not contract à/de with la or l': à la gare, à l'école, de la maison, de l'hôtel. These forms are required in standard written French."),("Contractions versus partitive articles","Du and des can be contractions (de + le/les) or partitive/indefinite articles. Meaning and the noun phrase decide: le toit du bâtiment (of the building) versus je mange du pain (some bread)."),("Common verb + preposition patterns","Learn the whole construction: parler à quelqu'un, parler de quelque chose, commencer à faire, décider de partir, réussir à comprendre. The preposition is selected by the verb and should not be translated mechanically."),("Chez, dans, en and à","Chez refers to a person's home, workplace or professional premises: chez Paul, chez le dentiste. Dans often means inside a bounded space; en/à are used in many country, city and transport expressions. Learn common place names with their preposition."),("Depuis versus pendant","Depuis marks a situation that began in the past and continues: J'étudie depuis deux ans. Pendant marks a bounded duration: J'ai étudié pendant deux ans. Use tense and context to show whether the activity continues.")],
"expressions":[("Je vais chez…","I'm going to…'s place / to…","Use with a person or professional: chez mes amis, chez le dentiste."),("à côté du…","next to the…","Du is the contraction of de + le."),("près des…","near the…","Des is the contraction of de + les here."),("depuis combien de temps ?","for how long?","Ask about a continuing situation.")],
"examples":[("Nous allons au cinéma après le travail.","We're going to the cinema after work.","À + le contracts to au."),("Elle revient des magasins.","She is coming back from the shops.","De + les contracts to des."),("Je parle à la professeure de mon projet.","I speak to the teacher about my project.","À la is not contracted; de mon introduces the topic."),("Il habite chez ses parents depuis trois mois.","He has been living at his parents' place for three months.","Chez identifies whose home; depuis marks a continuing period."),("J'ai travaillé pendant deux heures.","I worked for two hours.","Pendant describes a bounded duration.")],
"conversations":[("Planning where to meet",[("A","On se retrouve au café près de la gare ?"),("B","D'accord. Je passe chez ma sœur avant."),("A","Tu y vas depuis le centre-ville ?"),("B","Oui, je viens du bureau et j'arrive dans dix minutes.")],"A: Shall we meet at the café near the station? B: Okay. I'll stop at my sister's place first. A: Are you coming there from downtown? B: Yes, I'm coming from the office and I'll arrive in ten minutes.")],
"pronunciation":["Au and aux are both pronounced /o/ in standard French; spelling carries the grammatical difference.","Du /dy/ is distinct from dû /dy/ by accent and meaning, even though pronunciation is the same.","Keep the preposition attached to its noun phrase when speaking; do not insert a pause after au, du or chez."],
"exercises":[("Complete: Je vais ___ musée.",["à le","au","aux","du"],1,"À + le contracts to au."),("Complete: Elle revient ___ États-Unis.",["de les","des","du","de la"],1,"De + les contracts to des."),("Which phrase is correct?",["à l'école","au école","à le école","aux école"],0,"À + l' does not contract."),("Choose the natural construction.",["décider à partir","décider de partir","décider partir de","décider pour partir"],1,"Décider is followed by de + infinitive."),("Which phrase refers to a professional's premises?",["dans le médecin","chez le médecin","à le médecin","de le médecin"],1,"Chez is used with people and professionals."),("Which tense relationship does depuis usually express?",["A finished period only","A situation continuing from the past","A future deadline","A repeated command"],1,"Depuis commonly marks a situation that began earlier and continues now.")],
"speaking":["Describe your route using au, à la, aux, chez, dans and près de.","Create pairs that contrast du as a contraction and du as a partitive article.","Explain how long you have studied French using depuis, then describe a finished activity with pendant.","Practise the dialogue and replace the places and people."],
"summary":["À and de contract with le and les to form au, aux, du and des.","Do not contract with la or l'.","Learn verb + preposition patterns as complete constructions.","Chez refers to a person's home or professional premises; depuis and pendant express different time relationships."],
"homework":["Write twelve place phrases using the four contractions and the non-contracted forms.","Create a list of ten common verbs with their required prepositions and one example each.","Write six sentences contrasting depuis and pendant.","Proofread a short paragraph for missing or incorrect contractions."]
},
104: {
"level":"A2 – Elementary",
"title":"French Spelling, Punctuation and Written Conventions",
"goal":"Write clear, correctly formatted French by applying accents, apostrophes, capitalization, agreement and punctuation conventions.",
"objectives":["Use accents and cedillas accurately in familiar words.","Apply elision and apostrophes in common forms.","Follow French capitalization and punctuation conventions.","Proofread spelling, agreement and common written errors."],
"vocab":[("un accent aigu","acute accent","uhn ak-sahn ay-gü","/œ̃n ak.sɑ̃ e.ɡy/","École contient un accent aigu."),("un accent grave","grave accent","uhn ak-sahn grahv","/œ̃n ak.sɑ̃ ɡʁav/","Très contient un accent grave."),("un tréma","diaeresis","uhn tray-mah","/œ̃ tʁe.ma/","Noël contient un tréma."),("une cédille","cedilla","ün say-dee-yuh","/yn se.di.jə/","Français s'écrit avec une cédille."),("une apostrophe","apostrophe","ün ah-poh-strohf","/yn a.pɔs.tʁɔf/","L'apostrophe marque une élision."),("une majuscule","capital letter","ün mah-zhüs-kül","/yn ma.ʒys.kyl/","Un nom propre prend une majuscule."),("la ponctuation","punctuation","lah pohnk-tü-ah-syohn","/la pɔ̃k.ty.a.sjɔ̃/","La ponctuation clarifie le texte."),("une faute d'orthographe","spelling mistake","ün foht dohr-toh-grahf","/yn fot dɔʁ.tɔ.ɡʁaf/","Je corrige une faute d'orthographe.")],
"grammar":[("Accents change spelling and sometimes meaning","É, è, ê and ë have distinct spelling functions; ç marks soft c before a, o and u. Accents are not optional decoration. Distinguish a/à, ou/où, du/dû and sur/sûr by meaning and spelling."),("Elision and apostrophes","Before a vowel or silent h, common short words elide: je → j', le/la → l', ne → n', que → qu', de → d', and si → s' before il/ils. Do not elide before h aspiré: le héros, la honte."),("Capitalization","French weekdays, months, languages and nationalities used as adjectives are generally lowercase: lundi, janvier, le français, une auteure canadienne. Proper names and sentence beginnings take capitals. Nationality nouns are capitalized: un Français, une Canadienne."),("French punctuation spacing","Do not put a space before a comma or period. In standard French typography, a space (often a non-breaking or narrow non-breaking space in professional typesetting) precedes ; : ? and !. Digital platforms may handle narrow spaces differently; keep punctuation consistent and readable."),("Hyphens, apostrophes and proofreading","Use hyphens in inversion (Parlez-vous ?), compound numbers where required (vingt-deux) and certain compounds. Proofread in passes: accents/apostrophes, noun-adjective agreement, verb agreement, punctuation and meaning.")],
"expressions":[("Comment ça s'écrit ?","How is it spelled?","Ask someone to spell a word."),("Il manque un accent.","An accent is missing.","Useful when correcting spelling."),("Relis ton texte.","Read your text again.","Informal instruction; relisez is formal/plural."),("Il y a une faute de frappe.","There is a typo.","A typo is a typing error, not necessarily a grammar error.")],
"examples":[("J'étudie le français le mercredi.","I study French on Wednesdays.","Français is lowercase when naming the language; mercredi is also lowercase."),("Où habites-tu ?","Where do you live?","Où takes a grave accent; French typography places a space before the question mark."),("C'est à l'école, pas au collège.","It's at the school, not at the college.","C'est uses apostrophe for elision; à carries a grave accent."),("Noël arrive bientôt.","Christmas is coming soon.","Noël uses a tréma to show separate vowel pronunciation."),("Le héros arrive à huit heures !","The hero arrives at eight o'clock!","H aspiré blocks elision: le héros, not l'héros.")],
"conversations":[("Proofreading a message",[("A","Tu peux relire mon message ?"),("B","Bien sûr. Il manque un accent dans « où »."),("A","Et la ponctuation ?"),("B","Ajoute aussi une espace avant le point d'interrogation.")],"A: Can you reread my message? B: Of course. An accent is missing in où. A: And the punctuation? B: Also add a space before the question mark.")],
"pronunciation":["Accents can signal vowel quality or distinguish words; learn spelling and sound together.","The apostrophe marks a sound omission, not a pause; connect the remaining words smoothly.","Do not pronounce punctuation marks, but use pauses and intonation to make sentence boundaries clear."],
"exercises":[("Which spelling means 'where'?",["ou","où","oû","oue"],1,"Où means where; ou means or."),("Which word uses a cedilla?",["garçon","garcon","garçonne only","garçón"],0,"Ç makes c sound /s/ before o."),("Which is correctly capitalized?",["J'étudie le Français en Janvier.","J'étudie le français en janvier.","J'étudie le français en Janvier.","J'étudie le Français en janvier."],1,"Language names and months are lowercase in French."),("Choose the correct elision.",["le école","l'école","la école","l' école"],1,"Le becomes l' before a vowel or silent h; no space follows the apostrophe."),("Which form is correct before h aspiré?",["l'héros","le héros","l'héro","les héros only"],1,"H aspiré blocks elision, so write le héros."),("Which punctuation spacing is standard French typography?",["No space before ?","A space before ?","Two spaces before comma","A space before period"],1,"Standard French typography uses a space before ? and !; never before comma or period.")],
"speaking":["Read a short French paragraph aloud, pausing at commas, full stops and question marks.","Spell ten words aloud and identify the accent or apostrophe in each.","Explain the difference between a and à, ou and où, and du and dû.","Read your homework aloud after proofreading it for written conventions."],
"summary":["Accents, cedillas and apostrophes are part of correct spelling.","French weekdays, months and language names are generally lowercase.","Elision depends on sound and h type; h aspiré blocks it.","French punctuation has specific spacing conventions; proofreading should check meaning and form."],
"homework":["Write a 100-word message and check accents, apostrophes, capitals and punctuation.","Create ten minimal pairs such as a/à and ou/où with example sentences.","Proofread a paragraph and list each correction with its reason.","Practise spelling names, dates and addresses in French."]
},
105: {
"level":"B1 – Intermediate",
"title":"Verb + Preposition Patterns and Infinitive Complements",
"goal":"Use common French verb-preposition patterns accurately and construct sentences with one or more infinitives.",
"objectives":["Learn common verb + à/de + infinitive patterns.","Distinguish verb complements with à, de or no preposition.","Use a person-object plus de/à + infinitive correctly.","Place pronouns before the infinitive they belong to."],
"vocab":[("réussir à","to manage to; succeed in","ray-ü-seer ah","/ʁe.y.siʁ a/","Elle réussit à résoudre le problème."),("décider de","to decide to","day-see-day duh","/de.si.de də/","Nous décidons de partir."),("essayer de","to try to","eh-say-yay duh","/e.sɛ.je də/","J'essaie de comprendre."),("s'intéresser à","to be interested in","sahn-tay-ray-say ah","/sɛ̃.te.ʁe.se a/","Il s'intéresse à la politique."),("avoir besoin de","to need","ah-vwahr buh-zwan duh","/a.vwaʁ bə.zwɛ̃ də/","J'ai besoin de travailler."),("permettre à","to allow someone to","pehr-meh-truh ah","/pɛʁ.mɛtʁ a/","Cela me permet d'apprendre."),("empêcher de","to prevent from","ahn-pay-shay duh","/ɑ̃.pe.ʃe də/","La pluie nous empêche de sortir."),("renoncer à","to give up","ruh-nohn-say ah","/ʁə.nɔ̃.se a/","Elle renonce à voyager.")],
"grammar":[("Verbs followed by à + infinitive","Common patterns include réussir à, apprendre à, commencer à, continuer à and hésiter à. Memorise the verb together with its preposition and an example; English 'to' does not predict whether French uses à."),("Verbs followed by de + infinitive","Common patterns include décider de, essayer de, oublier de, promettre de, refuser de and éviter de. The de is part of the construction and should not be omitted."),("Verbs followed directly by an infinitive","Some verbs take a bare infinitive: vouloir partir, pouvoir venir, devoir travailler, aimer lire and préférer rester. Do not insert à or de automatically."),("A person plus infinitive","Some constructions use an indirect object before de + infinitive: demander à quelqu'un de faire quelque chose; permettre à quelqu'un de partir; conseiller à quelqu'un de se reposer. Others use direct object + de, such as empêcher quelqu'un de sortir."),("Pronouns with infinitives","Place the object pronoun before the infinitive it belongs to: Je veux le voir; elle essaie de lui parler; nous avons décidé d'y aller. In compound tenses, check which verb the pronoun belongs to.")],
"expressions":[("Je n'arrive pas à…","I can't manage to…","N'arriver à + infinitive expresses difficulty or inability."),("J'ai l'intention de…","I intend to…","A common de + infinitive construction."),("Ça m'empêche de…","That prevents me from…","Indirect object + empêcher de."),("Je tiens à…","I care about / insist on…","Often followed by a noun or infinitive.")],
"examples":[("Elle a réussi à terminer le rapport avant midi.","She managed to finish the report before noon.","Réussir is followed by à + infinitive."),("Nous avons décidé de reporter la réunion.","We decided to postpone the meeting.","Décider takes de + infinitive."),("Je veux lui expliquer la situation.","I want to explain the situation to him/her.","Lui belongs to expliquer and appears immediately before the infinitive."),("Le bruit empêche les étudiants de se concentrer.","The noise prevents the students from concentrating.","Empêcher quelqu'un de + infinitive."),("Il continue à apprendre malgré les difficultés.","He continues learning despite the difficulties.","Continuer à + infinitive.")],
"conversations":[("Discussing a project",[("A","Est-ce que tu as réussi à terminer l'analyse ?"),("B","Pas encore. J'essaie de vérifier les dernières données."),("A","Je peux demander à Léa de t'aider."),("B","Merci. Ça me permettrait d'avancer plus vite.")],"A: Did you manage to finish the analysis? B: Not yet. I'm trying to check the latest data. A: I can ask Léa to help you. B: Thanks. That would allow me to make faster progress.")],
"pronunciation":["In à and de constructions, keep the preposition audible even when it is unstressed.","Elide de to d' before a vowel: décider d'aller, essayer d'apprendre.","Practise the whole verb group as one rhythm unit, especially s'intéresser à and avoir besoin de."],
"exercises":[("Complete: Elle réussit ___ parler clairement.",["de","à","pour","sans"],1,"Réussir takes à + infinitive."),("Complete: Nous avons décidé ___ rester.",["à","de","pour","—"],1,"Décider takes de + infinitive."),("Which verb takes a bare infinitive?",["vouloir","décider","réussir","essayer"],0,"Vouloir is followed directly by an infinitive."),("Complete: Il empêche son frère ___ sortir.",["à","de","pour","en"],1,"Empêcher quelqu'un de faire quelque chose."),("Choose correct pronoun placement.",["Je veux voir le.","Je le veux voir.","Je veux le voir.","Je veux voir lui."],2,"The object pronoun comes immediately before the infinitive it belongs to."),("Complete: Elle s'intéresse ___ l'histoire.",["de","à","pour","en"],1,"S'intéresser takes à.")],
"speaking":["Make a three-column list of verbs followed by à, de and no preposition; add two examples to each.","Describe a challenge using réussir à, essayer de and ne pas arriver à.","Give advice using conseiller à quelqu'un de and permettre à quelqu'un de.","Read the dialogue aloud and identify every infinitive construction."],
"summary":["French infinitive complements are governed by the preceding verb.","Learn à, de or no preposition as part of each verb pattern.","Some verbs include a person object before the infinitive.","Place pronouns before the infinitive they belong to."],
"homework":["Write fifteen verb + infinitive patterns with original sentences.","Rewrite five sentences using object pronouns before the infinitive.","Write a short account of a goal using essayer de, réussir à and décider de.","Proofread for missing or extra prepositions."]
},
106: {
"level":"B2 – Upper Intermediate",
"title":"Present Participle, Gérondif and Non-finite Clauses",
"goal":"Use the present participle and gérondif to express simultaneous actions, manner, cause and condition with clear subject reference.",
"objectives":["Form regular present participles from the nous stem.","Use en + present participle for common gérondif meanings.","Recognise irregular forms and the difference between adjective and verbal participle.","Avoid dangling or ambiguous gérondif constructions."],
"vocab":[("en parlant","while speaking","ahn par-lahn","/ɑ̃ paʁ.lɑ̃/","En parlant lentement, il est plus clair."),("en travaillant","while working","ahn trah-vah-yahn","/ɑ̃ tʁa.va.jɑ̃/","Elle écoute de la musique en travaillant."),("tout en sachant","while knowing; despite knowing","too-tahn sah-shahn","/tu.tɑ̃ sa.ʃɑ̃/","Tout en sachant le risque, il continue."),("étant donné","given; considering","ay-tahn doh-nay","/e.tɑ̃ dɔ.ne/","Étant donné la situation, nous attendons."),("un participe présent","present participle","uhn par-tee-seep pray-zahn","/œ̃ paʁ.ti.sip pʁe.zɑ̃/","Parlant est un participe présent."),("un gérondif","gerund","uhn zhay-rohn-deef","/œ̃ ʒe.ʁɔ̃.dif/","En lisant est un gérondif."),("simultané","simultaneous","see-mül-tah-nay","/si.my.ta.ne/","Les deux actions sont simultanées."),("une circonstance","a circumstance","ün seer-kohn-stahns","/yn siʁ.kɔ̃.stɑ̃s/","La circonstance explique le choix.")],
"grammar":[("Forming the present participle","Take the nous form of the present tense, remove -ons and add -ant: nous parlons → parlant; nous finissons → finissant; nous prenons → prenant. Important irregular forms include étant, ayant and sachant."),("The gérondif: en + present participle","Form en parlant, en lisant, en travaillant. It commonly expresses two simultaneous actions by the same subject, manner or means: Elle apprend en pratiquant."),("Cause, condition and concession","The gérondif can express cause or condition in context: En travaillant régulièrement, tu progresseras. Tout en reconnaissant le problème, il propose une solution introduces concession."),("Same-subject requirement","The understood subject of the gérondif is normally the subject of the main clause: En arrivant, j'ai appelé. Avoid dangling constructions where the person doing the participle action is unclear or different from the main-clause subject."),("Participle versus adjective","A present participle is verbal and can take complements; an adjective agrees in gender and number: des personnes convaincantes. The gérondif always uses en + invariable present participle. Do not confuse it with the English -ing form in every context.")],
"expressions":[("En tenant compte de…","Taking … into account","Gérondif phrase used to introduce a consideration."),("Tout en reconnaissant que…","While acknowledging that…","Concession with tout en + participle."),("En d'autres termes,…","In other words,…","Useful for reformulation; not itself a gérondif."),("Étant donné que…","Given that…","Fixed connector followed by a clause; distinguish it from étant donné + noun.")],
"examples":[("En comparant les deux rapports, nous avons relevé plusieurs écarts.","By comparing the two reports, we identified several differences.","Gérondif expresses the means or simultaneous action by nous."),("Elle prend des notes tout en écoutant les intervenants.","She takes notes while listening to the speakers.","Tout en emphasises simultaneous actions."),("En réduisant les coûts, l'entreprise pourrait améliorer sa marge.","By reducing costs, the company could improve its margin.","The gérondif introduces a condition or means."),("Étant donné que les données sont incomplètes, la conclusion reste provisoire.","Given that the data are incomplete, the conclusion remains provisional.","Étant donné que introduces a finite clause, not a gérondif."),("Les explications convaincantes ont facilité la décision.","The convincing explanations made the decision easier.","Convaincantes is an agreeing adjective, not a gérondif.")],
"conversations":[("Explaining a method",[("A","Comment as-tu résolu ce problème ?"),("B","En comparant les résultats et en vérifiant les sources."),("A","Tu as travaillé seul ?"),("B","Oui, tout en demandant conseil lorsque c'était nécessaire.")],"A: How did you solve this problem? B: By comparing the results and checking the sources. A: Did you work alone? B: Yes, while asking for advice whenever necessary.")],
"pronunciation":["The -ant ending is pronounced /ɑ̃/; do not add a final consonant.","In en arrivant, the n links into the vowel; practise the phrase smoothly.","Keep the main-clause subject clear so listeners know who performs both actions."],
"exercises":[("Form the present participle of nous parlons.",["parlé","parlant","parlons","parlante"],1,"Remove -ons and add -ant."),("Which is the gérondif?",["parlant","en parlant","parle","parlé"],1,"The gérondif is en + present participle."),("Which sentence has a clear same subject?",["En arrivant, le train est parti.","En arrivant, j'ai appelé ma collègue.","En arrivant, la pluie a commencé.","En arrivant, la porte était ouverte."],1,"The subject of en arrivant is je, which is also the subject of j'ai appelé."),("Which is an irregular present participle?",["parlant","finissant","sachant","vendant"],2,"Savoir has the irregular present participle sachant."),("What does tout en + participle often express?",["Only future time","Concession or simultaneous action","A command","A completed past action"],1,"Tout en can emphasise concession or simultaneity."),("Which word is an agreeing adjective?",["en convainquant","convaincantes","en travaillant","sachant"],1,"Convaincantes agrees with the feminine plural noun.")],
"speaking":["Explain a process using at least six gérondif phrases.","Create two examples each for simultaneity, manner and condition.","Correct three dangling gérondif sentences and explain the subject problem.","Contrast étant donné que with en tenant compte de in context."],
"summary":["The present participle is formed from the nous stem + -ant, with key irregular forms.","The gérondif is en + present participle and often expresses simultaneity or means.","The gérondif normally shares its subject with the main clause.","Distinguish verbal participles, gérondifs and agreeing adjectives."],
"homework":["Write a 150-word explanation of a process using at least eight gérondif forms.","Write five sentences with tout en to express concession or simultaneity.","Edit a paragraph for unclear gérondif subjects.","Create a reference table of regular and irregular present participles."]
},
107: {
"level":"C1 – Advanced",
"title":"Canadian French Sociolinguistics, Identity and Register",
"goal":"Interpret language variation across Canadian French communities and adapt speech to audience without stereotyping regional or social varieties.",
"objectives":["Distinguish regional, social, situational and individual variation.","Recognise differences among Quebec, Acadian and other Canadian French contexts.","Explain register, code-switching, borrowing and language attitudes neutrally.","Choose forms appropriate to audience, purpose and relationship."],
"vocab":[("une variété régionale","regional variety","ün vah-ree-ay-tay ray-zhyoh-nal","/yn va.ʁje.te ʁe.ʒjɔ.nal/","Une variété régionale reflète une histoire locale."),("un sociolecte","sociolect","uhn soh-syoh-lekt","/œ̃ sɔ.sjɔ.lɛkt/","Un sociolecte dépend d'un groupe social."),("un registre","register","uhn ruh-zhest-ruh","/œ̃ ʁə.ʒistʁ/","Le registre change selon la situation."),("un emprunt","a loanword","uhn ahn-prohn","/œ̃n ɑ̃.pʁœ̃/","Un emprunt peut venir d'une autre langue."),("une alternance codique","code-switching","ün al-tehr-nahns koh-deek","/yn al.tɛʁ.nɑ̃s kɔ.dik/","L'alternance codique dépend du contexte."),("une norme","a norm/standard","ün nohrm","/yn nɔʁm/","La norme écrite est partagée largement."),("une communauté","a community","ün koh-mü-noh-tay","/yn kɔ.my.no.te/","Chaque communauté a ses usages."),("un préjugé linguistique","language prejudice","uhn pray-zhü-zhay lan-güis-teek","/œ̃ pʁe.ʒy.ʒe lɛ̃.ɡɥis.tik/","Évitons les préjugés linguistiques.")],
"grammar":[("Variation is systematic, not random error","Regional and social varieties have patterns in pronunciation, vocabulary and grammar. A form may be appropriate in one community or situation and not in another. Describe the pattern and context rather than labelling a whole variety as incorrect."),("Regional diversity within Canada","Quebec French is influential but does not represent all Canadian French. Acadian, Franco-Ontarian, Franco-Manitoban and other communities have distinct histories and usage. Variation also exists within each region by age, setting and speaker."),("Register and audience design","Choose formal, neutral or informal forms based on audience, purpose, relationship and medium. Tu/vous, slang, contractions and professional vocabulary are social choices, not simply levels of intelligence or correctness."),("Borrowing and code-switching","French speakers may borrow words or alternate languages in multilingual settings. Distinguish established borrowings, occasional code-switching and avoidable calques. Explain the speaker's context rather than assuming a single motive."),("Language attitudes and identity","Accent can signal belonging, identity or personal history, but it cannot reliably reveal every fact about a speaker. Avoid stereotypes, ranking accents or assuming all members of a community speak alike.")],
"expressions":[("Selon le contexte,…","Depending on the context,…","Signals that usage changes by situation."),("Cette forme est courante dans…","This form is common in…","Describe regional usage precisely."),("Il faut distinguer la norme écrite de l'usage oral.","We must distinguish the written standard from spoken usage.","Useful in linguistic discussion."),("Les usages varient d'une communauté à l'autre.","Usage varies from one community to another.","Avoids overgeneralising.")],
"examples":[("Cette expression est courante au Québec, mais elle n'est pas universelle au Canada.","This expression is common in Quebec, but it is not universal in Canada.","The sentence distinguishes a regional pattern from a national generalisation."),("Dans un courriel officiel, je choisirais un registre plus neutre.","In an official email, I would choose a more neutral register.","Register depends on purpose and audience."),("L'alternance codique peut refléter le contexte multilingue d'une conversation.","Code-switching can reflect the multilingual context of a conversation.","The statement avoids assuming a single cause."),("Il vaut mieux décrire les caractéristiques d'un accent que le classer comme meilleur ou pire.","It is better to describe an accent's features than rank it as better or worse.","A neutral sociolinguistic stance avoids accent prejudice.")],
"conversations":[("Discussing regional speech",[("A","Est-ce que cette expression est utilisée partout au Canada ?"),("B","Non. Elle est courante dans certains milieux québécois, mais les usages varient."),("A","Et l'Acadie ?"),("B","Il existe aussi plusieurs variétés acadiennes, avec leurs propres caractéristiques.")],"A: Is this expression used everywhere in Canada? B: No. It is common in some Quebec contexts, but usage varies. A: And Acadia? B: There are also several Acadian varieties, with their own features.")],
"pronunciation":["When comparing accents, describe observable features such as vowel quality, rhythm or consonant realisation.","Avoid imitating an accent as a joke; practise comprehension and respectful description.","Listen to speakers from different communities and note variation without treating one speaker as representative of all."],
"exercises":[("Which statement about Canadian French is accurate?",["Quebec French represents every Canadian speaker","Canada has several French-speaking communities and varieties","All Canadian French accents are identical","Regional variation is random"],1,"Canadian French is diverse across regions and communities."),("What determines register?",["Only grammar difficulty","Audience, purpose, relationship and medium","The speaker's intelligence","The number of syllables"],1,"Register is selected according to the communicative situation."),("What is code-switching?",["A spelling error","Alternating between languages or varieties in discourse","A verb tense","A punctuation mark"],1,"Code-switching is alternation between languages or varieties."),("How should an accent be described?",["As superior or inferior","By concrete linguistic features and context","As proof of a person's education","As identical to all speakers from a region"],1,"Describe observable features without ranking or stereotyping."),("Which phrase avoids overgeneralisation?",["All Quebecers say…","This form is common in some Quebec contexts","No Canadian speaker uses…","Every Acadian speaks the same way"],1,"The phrase limits the claim to a grounded context."),("What is a loanword?",["A borrowed word from another language","A word with no meaning","A formal verb ending","A silent letter"],0,"An emprunt is a word borrowed from another language.")],
"speaking":["Compare two authentic Canadian French audio samples and describe three observable differences without ranking the speakers.","Explain how you would adapt a message for a friend, a colleague and a public institution.","Discuss a language-attitude claim and identify any unsupported generalisation.","Present a short overview of Quebec, Acadian and other Canadian French varieties with careful qualifications."],
"summary":["Canadian French includes several regional and social varieties.","Register depends on audience, purpose, relationship and medium.","Borrowing and code-switching occur in multilingual contexts and need contextual interpretation.","Describe variation precisely and avoid stereotypes or accent hierarchies."],
"homework":["Listen to two speakers from different Canadian French communities and create a neutral feature comparison.","Rewrite one message in informal, neutral and formal registers.","Find five regional expressions and document region, meaning, register and a neutral alternative.","Write a 250-word reflection on language variation and identity without making unsupported generalisations."]
}
}

def _make_questions(spec):
    vocab = spec["vocab"]
    questions = []
    for i, item in enumerate(vocab[:6]):
        correct = item[1]
        distractors = [vocab[(i+j) % len(vocab)][1] for j in (1,2,3)]
        options = [correct] + distractors
        shift = i % 4
        options = options[shift:] + options[:shift]
        questions.append((f"What does « {item[0]} » mean in this lesson?", options, options.index(correct), f"« {item[0]} » means {correct}."))
    grammar = spec["grammar"]
    for i, (title, explanation) in enumerate(grammar[:4]):
        options = [explanation, grammar[(i+1)%len(grammar)][1], grammar[(i+2)%len(grammar)][1], grammar[(i+3)%len(grammar)][1]]
        shift = (i+1) % 4
        options = options[shift:] + options[:shift]
        questions.append((f"Which explanation best describes “{title}”?", options, options.index(explanation), explanation))
    return questions

def _build(lesson_id, spec):
    vocabulary = [(fr, meaning, pronunciation, ipa, example) for fr, meaning, pronunciation, ipa, example in spec["vocab"]]
    exercises = _make_questions(spec)
    return {
        "id": lesson_id,
        "level": spec["level"],
        "title": spec["title"],
        "goal": spec["goal"],
        "objectives": spec["objectives"],
        "vocab": vocabulary,
        "vocabulary": vocabulary,
        "grammar": spec["grammar"],
        "expressions": [(phrase, meaning, context) for phrase, meaning, context in spec["expressions"]],
        "examples": spec["examples"],
        "conversations": spec["conversations"],
        "pronunciation": spec["pronunciation"],
        "exercises": exercises,
        "assessment": exercises,
        "speaking": spec["speaking"],
        "summary": spec["summary"],
        "homework": spec["homework"],
    }

EXTENSION_LESSONS = {lesson_id: _build(lesson_id, spec) for lesson_id, spec in LESSON_SPECS.items()}
